        ["To claim your Desert set rewards, speak to Hassan in Al Kharid Palace, Ali the Mayor in Pollnivneach, the Golem in Uzer, or myself."] = "Para reclamar las recompensas del conjunto Desierto, habla con Hassan en el Palacio Al Kharid, con Ali el Mayor en Pollnivneach, con el Golem en Uzer o conmigo mismo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Choose an option:"] = "Elige una opción:",
        ["Desert amulet 1"] = "Amuleto del desierto 1",
        ["Desert amulet 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Amuleto del desierto 1? Sí, pero me temo que te costaría 1.500 coins.",
        ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
        ["Yes"] = "si",
        ["[You're handed another Desert amulet 1.]"] = "[Te entregan otro amuleto del Desierto 1.]",
        ["No thanks."] = "No, gracias.",
        ["Desert amulet 2"] = "Amuleto del desierto 2",
        ["Desert amulet 2? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Amuleto del desierto 2? Sí, pero me temo que te costaría 7.500 coins.",
        ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
        ["[You're handed another Desert amulet 2.]"] = "[Te entregan otro amuleto del Desierto 2.]",
        ["Desert amulet 3"] = "Amuleto del desierto 3",
        ["Desert amulet 3? Yes, but I'm afraid it would cost you 25,000 coins."] = "¿Amuleto del desierto 3? Sí, pero me temo que te costaría 25.000 coins.",
        ["Purchase another for 25,000 coins?"] = "¿Comprar otro por 25.000 coins?",
        ["[You're handed another Desert amulet 3.]"] = "[Te entregan otro amuleto del Desierto 3.]",
        ["Desert amulet 4"] = "Amuleto del desierto 4",
        ["Desert amulet 4? Yes, but I'm afraid it would cost you 50,000 coins."] = "¿Amuleto del desierto 4? Sí, pero me temo que te costaría 50.000 coins.",
        ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
        ["[You're handed another Desert amulet 4.]"] = "[Te entregan otro amuleto del Desierto 4.]",
        ["Can you convert my flasks into normal vials for me?"] = "¿Pueden convertir mis matraces en viales normales para mí?",
        ["Sorry, you don't seem to have anything I can use. Make sure you have at least 1 flask!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener al menos 1 matraz!",
        ["Certainly. I think I can make use of the flasks, so I'll give you the vials for free."] = "Por supuesto. Creo que puedo utilizar los matraces, así que te daré los viales gratis.",
        ["Convert the flasks, and I will keep any empty flasks?"] = "¿Convertir los matraces y guardaré los matraces vacíos?",
        ["There you go, that's the best I can do!"] = "Ahí lo tienes, ¡eso es lo mejor que puedo hacer!",
        ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    },
    ["Zahwa"] = {
        ["Are you alright?"] = "¿Estás bien?",
        ["Do I look alright?"] = "¿Me veo bien?",
        ["Nurse!"] = "¡Enfermera!",
        ["It's just a flesh wound."] = "Es sólo una herida superficial.",
        ["Yeah. The nurses here are... wonderful!"] = "Sí. Las enfermeras aquí son... ¡maravillosas!",
        ["Hi!"] = "¡Hola!",
        ["I could've 'ad 'im!"] = "¡Podría haberlo dicho!",
        ["Er..."] = "Eh...",
        ["I was robbed!"] = "¡Me robaron!",
        ["Right."] = "Correcto.",
        ["It was rigged, I tell you!"] = "¡Estaba amañado, te lo digo!",
        ["Uh-huh."] = "Ajá.",
        ["Leave me alone."] = "Déjame en paz.",
        ["Ughhhh..."] = "Ughhh...",
        ["Can't...go...on."] = "No puedo... continuar.",
        ["Leave...me...behind."] = "Déjame... atrás.",
        ["I'll leave you here, okay?"] = "Te dejo aquí, ¿vale?",
        ["Oh. Okay."] = "Ah. Bueno.",
        ["Aargh."] = "Argh.",
        ["Are you feeling okay?"] = "¿Te sientes bien?",
        ["He got quite injured in the earthquake, I'm afraid."] = "Me temo que resultó bastante herido en el terremoto.",
    },
    ["Zaida"] = {
        ["Good day! How can I help you?"] = "¡Buenos días! ¿Le puedo ayudar en algo?",
        ["Nice yak you have there."] = "Bonito yak el que tienes ahí.",
        ["Thank you kindly! As you can see we've been quite busy; we're just on our way to the Grand Exchange to start shifting all this treasure we found."] = "¡Muchas gracias! Como puedes ver hemos estado bastante ocupados; Estamos de camino al Grand Exchange para comenzar a trasladar todo este tesoro que encontramos.",
        ["You found all of this?"] = "¿Encontraste todo esto?",
        ["That I did! Let me take a moment to tell you the wonders of treasure trails."] = "¡Eso hice! Permítanme tomarme un momento para contarles las maravillas de los senderos del tesoro.",
        ["Choose an option:"] = "Elige una opción:",
        ["Talk about treasure trails."] = "Habla de senderos del tesoro.",
        ["Select an Option"] = "Selecciona una opción",
        ["Tell me more about treasure trails."] = "Cuéntame más sobre los senderos del tesoro.",
        ["Across the world there is treasure buried that can be recovered... if you know where to look!"] = "En todo el mundo hay tesoros enterrados que se pueden recuperar... ¡si sabes dónde buscar!",
        ["If you're lucky in your adventures you may come across something called a clue scroll. You may find some monsters drop them when they die, or may discover one while you are training your skills."] = "Si tienes suerte en tus aventuras, es posible que te encuentres con algo llamado pergamino de pistas. Es posible que algunos monstruos los dejen caer cuando mueren, o que descubras uno mientras entrenas tus habilidades.",
        ["When you read the clue scroll, it will point you to somewhere else on Gielinor. The challenge here is deciphering where the clue scroll wants you to go."] = "Cuando leas el pergamino de pistas, te indicará otro lugar en Gielinor. El desafío aquí es descifrar dónde quiere que vayas el pergamino de pistas.",
        ["But if you can figure it out, head to that location and do what the clue asks of you."] = "Pero si puedes resolverlo, dirígete a ese lugar y haz lo que te pida la pista.",
        ["Treasure trails can be multiple steps, so don't be surprised if it leads you to another clue scroll."] = "Los senderos del tesoro pueden consistir en varios pasos, así que no te sorprendas si te lleva a otro pergamino de pistas.",
        ["Keep going and eventually you will find the treasure you seek!"] = "¡Continúa y eventualmente encontrarás el tesoro que buscas!",
        ["If you happen to find a clue scroll that you're unable to complete, I'll take it off your hands in return for an easier one."] = "Si encuentras un pergamino de pistas que no puedes completar, te lo quitaré de las manos a cambio de uno más fácil.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["Where can I get my own clue scrolls from?"] = "¿Dónde puedo conseguir mis propios pergaminos de pistas?",
        ["What type of clue scroll would you like to know more about?"] = "¿Sobre qué tipo de pergamino de pistas te gustaría saber más?",
        ["Easy clues."] = "Pistas fáciles.",
        ["Some of the ways you can get easy clue scrolls include killing various low-level monsters across Gielinor, by pickpocketing members of H.A.M. (they have a hideout in Lumbridge, don't tell them I let you know!), and as an uncommon drop when defeating evil trees."] = "Algunas de las formas en que puedes obtener pergaminos de pistas fáciles incluyen matar varios monstruos de bajo nivel en Gielinor, robando a miembros de H.A.M. (tienen un escondite en Lumbridge, ¡no les digas que te lo haré saber!), y como un botín poco común al derrotar árboles malvados.",
        ["Medium clues."] = "Pistas medianas.",
        ["Some of the ways you can get medium clue scrolls include killing various mid-level monsters across Gielinor and purchasing one from Stanley Limelight with thaler."] = "Algunas de las formas en que puedes obtener pergaminos de pistas medianos incluyen matar varios monstruos de nivel medio en Gielinor y comprar uno en Stanley Limelight con táleros.",
        ["Hard clues."] = "Pistas difíciles.",
        ["Some of the ways you can get hard clue scrolls include killing various high-level monsters across Gielinor, by pickpocketing dwarf traders and elven clan workers, and purchasing one from Stanley Limelight with thaler."] = "Algunas de las formas en que puedes obtener pergaminos de pistas difíciles incluyen matar varios monstruos de alto nivel en Gielinor, robar a comerciantes enanos y trabajadores de clanes elfos, y comprar uno de Stanley Limelight con táleros.",
        ["Elite clues."] = "Pistas de élite.",
        ["Some of the ways you can get elite clue scrolls include killing various high-level monsters across Gielinor, by pickpocketing Waiko islanders and elven clan workers, using crystal triskelion keys, and purchasing one from Stanley Limelight with thaler."] = "Algunas de las formas en que puedes obtener pergaminos de pistas de élite incluyen matar varios monstruos de alto nivel en Gielinor, robar a los isleños Waiko y trabajadores del clan élfico, usar llaves de triskelion de cristal y comprar uno en Stanley Limelight con táleros.",
        ["You can also get a guaranteed elite clue scroll once a week from treasure chests in your aquarium and by defeating the Skeletal Horror."] = "También puedes obtener un pergamino de pistas de élite garantizado una vez a la semana en los cofres del tesoro de tu acuario y al derrotar al Skeletal Horror.",
        ["Master clues."] = "Pistas maestras.",
        ["Ah, the master clues! The rarest of the rare. The best way to get your hands on these is by completing treasure trails as you'll occasionally find them within the reward caskets."] = "¡Ah, las pistas maestras! Lo más raro de lo raro. La mejor manera de conseguirlos es completando senderos del tesoro, ya que ocasionalmente los encontrarás dentro de los cofres de recompensa.",
        ["There's also a small chance that you will get a master clue from anything that normally gives you an elite clue - it's quite rare though so good luck!"] = "También existe una pequeña posibilidad de que obtengas una pista maestra de cualquier cosa que normalmente te dé una pista de élite; aunque es bastante raro, ¡así que buena suerte!",
        ["Where did clue scrolls originate?"] = "¿Dónde se originaron los pergaminos de pistas?",
        ["Ha! Well that's a tricky question even for me. Listen, I don't rightly know but there are some curiosities to the whole business."] = "¡Ja! Bueno, esa es una pregunta complicada incluso para mí. Escuche, no lo sé exactamente, pero hay algunas curiosidades en todo este asunto.",
        ["As far as I can tell, all of this is setup by a fella by the name of Uri. I've been hunting these clue scrolls for years and his supply of treasures seems pretty limitless."] = "Hasta donde puedo decir, todo esto lo organizó un tipo llamado Uri. He estado buscando estos pergaminos de pistas durante años y su suministro de tesoros parece bastante ilimitado.",
        ["Of course, if that wasn't strange enough - there's also someone who looks identical to Uri, who seems set on sabotaging the whole thing."] = "Por supuesto, si eso no fuera lo suficientemente extraño, también hay alguien que luce idéntico a Uri, que parece decidido a sabotear todo.",
        ["Then there are the wizards that pop up from time to time who may try to attack you."] = "Luego están los magos que aparecen de vez en cuando y que pueden intentar atacarte.",
        ["And even more bizarre than that? All the people that these clue scrolls point to - if you ask them about it afterwards, they have no idea what you're talking about! Like it never happened!"] = "¿Y aún más extraño que eso? Todas las personas a las que apuntan estos pergaminos de pistas: si luego les preguntas al respecto, ¡no tienen idea de lo que estás hablando! ¡Como si nunca hubiera sucedido!",
        ["I know what you're thinking, this all sounds like the ramblings of a mad woman. But I swear, every word I say is true!"] = "Sé lo que estás pensando, todo esto suena como las divagaciones de una loca. ¡Pero lo juro, cada palabra que digo es verdad!",
        ["Basically, even after all these years I still have no idea. If you ever figure it out, I'd love to know. Just to put my mind at ease if anything else."] = "Básicamente, incluso después de todos estos años todavía no tengo idea. Si alguna vez lo descubres, me encantaría saberlo. Sólo para tranquilizarme, en todo caso.",
        ["Who are you?"] = "¿Quién eres?",
        ["The name's Zaida, and this brute here is Nigel."] = "El nombre es Zaida, y este bruto aquí es Nigel.",
        ["Do you want some advice? Scrap that, I'm going to give it to you anyway. You don't get anywhere in life without putting in hard work."] = "¿Quieres un consejo? Desecha eso, te lo daré de todos modos. No se llega a ninguna parte en la vida sin trabajar duro.",
        ["I'm a treasure hunter, have been my whole life. Turns out there is treasure buried across the whole of Gielinor and if you spend the time looking there is more wealth than you can imagine just waiting for someone to discover it."] = "Soy un cazador de tesoros, lo he sido toda mi vida. Resulta que hay tesoros enterrados en todo Gielinor y si pasas el tiempo buscando, hay más riqueza de la que puedas imaginar esperando a que alguien la descubra.",
        ["I can't tell you what to do with your life but I'd give up that adventuring lark and focus on finding these trasures."] = "No puedo decirte qué hacer con tu vida, pero dejaría esa aventura aventurera y me concentraría en encontrar estos tesoros.",
        ["After all, we all know that money buys happiness."] = "Después de todo, todos sabemos que el dinero compra la felicidad.",
        ["Goodbye."] = "Adiós.",
        ["May good fortune come your way!"] = "¡Que la buena suerte te llegue!",
        ["Claim a free clue scroll."] = "Reclama un pergamino de pistas gratuito.",
        ["I'd like to offer you a clue scroll, but it seems you don't have any room to carry one at the moment."] = "Me gustaría ofrecerte un pergamino de pistas, pero parece que no tienes espacio para llevar uno en este momento.",
        ["I'd like to offer you this elite clue scroll. May it bring you good fortune!"] = "Me gustaría ofrecerles este pergamino de pistas de élite. ¡Que te traiga buena suerte!",
        ["[Zaida hands you a sealed clue scroll.]"] = "[Zaida te entrega un pergamino de pistas sellado.]",
        ["I'd like to offer you this elite clue scroll but it seems you already have some. Talk to me again when you have completed one of them."] = "Me gustaría ofrecerte este pergamino de pistas de élite, pero parece que ya tienes algunos. Hablame de nuevo cuando hayas completado uno de ellos.",
        ["I'd like to offer you this hard clue scroll. May it bring you good fortune!"] = "Me gustaría ofrecerles este pergamino de pistas difíciles. ¡Que te traiga buena suerte!",
        ["I'd like to offer you this hard clue scroll but it seems you already have some. Talk to me again when you have completed one of them."] = "Me gustaría ofrecerte este pergamino de pistas difíciles, pero parece que ya tienes algunas. Hablame de nuevo cuando hayas completado uno de ellos.",
        ["I'd like to offer you this medium clue scroll. May it bring you good fortune!"] = "Me gustaría ofrecerles este pergamino de pistas mediano. ¡Que te traiga buena suerte!",
        ["I'd like to offer you this medium clue scroll but it seems you already have some. Talk to me again when you have completed one of them."] = "Me gustaría ofrecerte este pergamino de pistas mediano, pero parece que ya tienes algunos. Hablame de nuevo cuando hayas completado uno de ellos.",
        ["I'd like to offer you this easy clue scroll. May it bring you good fortune!"] = "Me gustaría ofrecerles este sencillo pergamino de pistas. ¡Que te traiga buena suerte!",
        ["I'd like to offer you this easy clue scroll but it seems you already have some. Talk to me again when you have completed one of them."] = "Me gustaría ofrecerte este sencillo pergamino de pistas, pero parece que ya tienes algunos. Hablame de nuevo cuando hayas completado uno de ellos.",
        ["Downgrade a clue scroll."] = "Degradar un pergamino de pistas.",
        ["I can exchange any clue scroll you have for one of a lower tier. Just give me the clue you want to exchange."] = "Puedo intercambiar cualquier pergamino de pista que tengas por uno de un nivel inferior. Sólo dame la pista que quieres intercambiar.",
        ["Open the shop."] = "Abre la tienda.",
        ["What do you have for sale?"] = "¿Qué tienes a la venta?",
        ["I have titles, a pet, clue scrolls and more! Let's not forget the Globetrotter outfit that will help you on your trails."] = "¡Tengo títulos, una mascota, pergaminos de pistas y más! No olvidemos el conjunto Globetrotter que te ayudará en tus senderos.",
        ["Reclaim the Globetrotter outfit"] = "Recupera el traje de Globetrotter",
        ["Hi there. I would like to reclaim my Globetrotter outfit please."] = "Hola. Me gustaría recuperar mi traje de Globetrotter, por favor.",
        ["I'm sorry, you don't own any pieces of the outfit. Would you like to see the store?"] = "Lo siento, no posees ninguna pieza del conjunto. ¿Quieres ver la tienda?",
        ["Open the Treasure Trails Reward Shop?"] = "¿Abrir la tienda de recompensas Treasure Trails?",
        ["Yes."] = "Sí.",
        ["Goodbye!"] = "¡Adiós!",
        ["You already have all of your owned pieces of the outfit!"] = "¡Ya tienes todas tus piezas del conjunto!",
        ["[Each outfit piece has a return fee of 500,000, due to it having combat stats.<br>To return all owned outfit pieces this will cost [number] coins.]"] = "[Cada pieza de vestimenta tiene una tarifa de devolución de 500,000, debido a que tiene estadísticas de combate. <br> Para devolver todas las piezas de vestimenta que posee, esto costará [número] coins.]",
        ["Pay the return fee?"] = "¿Pagar la tarifa de devolución?",
        ["You do not have enough space in your backpack, come back later!"] = "No tienes suficiente espacio en tu backpack, ¡vuelve más tarde!",
        ["Zaida returns your [item] to your backpack."] = "Zaida devuelve su [item] a su backpack.",
        ["That's everything, goodbye!"] = "Eso es todo, ¡adiós!",
        ["Thank you, goodbye!"] = "¡Gracias, adiós!",
        ["Reclaim the Charos Clue Carrier"] = "Reclama el portador de pistas Charos",
        ["You already have that item."] = "Ya tienes ese artículo.",
        ["Easy clues are the most basic of all treasure trails; I can't trade this for anything simpler. Try asking around for assistance if you are stuck."] = "Las pistas fáciles son las más básicas de todos los senderos del tesoro; No puedo cambiar esto por nada más simple. Intente pedir ayuda si está atascado.",
        ["Do you want to trade that clue scroll for a lower tier clue scroll?"] = "¿Quieres cambiar ese pergamino de pistas por un pergamino de pistas de nivel inferior?",
        ["Trade your [tier] clue scroll for a lower tier clue scroll?"] = "¿Cambiar tu pergamino de pistas [tier] por un pergamino de pistas de nivel inferior?",
        ["Elite clue scroll."] = "Pergamino de pistas de élite.",
        ["There you go! Good luck with the new clue scroll!"] = "¡Ahí lo tienes! ¡Buena suerte con el nuevo pergamino de pistas!",
        ["Hard clue scroll."] = "Desplazamiento de pistas difíciles.",
        ["Medium clue scroll."] = "Desplazamiento de pistas mediano.",
        ["Easy clue scroll."] = "Desplazamiento de pistas fácil.",
        ["Cancel."] = "Cancelar.",
        ["Never mind. Good luck with the clue scroll!"] = "No importa. ¡Buena suerte con el pergamino de pistas!",
    },
    ["Zaman"] = {
        ["Hey, I'm Zaman, how can I help you friend?"] = "Hola, soy Zaman, ¿en qué puedo ayudarte amigo?",
        ["You're Zaman? Nice to meet you. Can I ask you something?"] = "¿Eres Zaman? Encantado de conocerlo. ¿Puedo preguntarte algo?",
        ["What would you like to ask?"] = "¿Qué te gustaría preguntar?",
        ["Open Countdown to Menaphos Calendar"] = "Abrir cuenta atrás para el calendario Menaphos",
        ["*(Countdown to Menaphos interface opens.)*"] = "*(Se abre la cuenta atrás para la interfaz Menaphos.)*",
        ["What's all this increased activity in the desert about?"] = "¿A qué se debe todo este aumento de actividad en el desierto?",
        ["Rumour has spread that the great city of Menaphos will be opening it's{{Sic}} gates."] = "Se ha extendido el rumor de que la gran ciudad de Menaphos abrirá sus puertas {{Sic}}.",
        ["How do you know this?"] = "¿Cómo sabes esto?",
        ["We were once citizens but were exiled a long time ago. Mutterings have recently spread through some of our contacts that something's happening soon."] = "Una vez fuimos ciudadanos pero fuimos exiliados hace mucho tiempo. Recientemente se han difundido entre algunos de nuestros contactos rumores de que algo sucederá pronto.",
        ["Are you going to try and go back inside then?"] = "¿Vas a intentar volver a entrar entonces?",
        ["We're hoping that if we repent and change our ways, it will be viewed favourably."] = "Esperamos que si nos arrepentimos y cambiamos nuestra conducta, será visto favorablemente.",
        ["If you speak to myself or my friend Almarid who is currently outside the gates each day, we'll give you some of our erm... antiquities, so we can repent our thieving ways of old."] = "Si hablas conmigo o con mi amigo Almarid, que actualmente está fuera de las puertas todos los días, te daremos algunas de nuestras erm... antigüedades, para que podamos arrepentirnos de nuestras costumbres de ladrón de antaño.",
        ["Anything else I should know?"] = "¿Algo más que deba saber?",
        ["I can teleport you to Almarid if you like?"] = "¿Puedo teletransportarte a Almarid si quieres?",
        ["Teleport to Almarid?"] = "¿Teletransportarse a Almarid?",
        ["Yes."] = "Sí.",
        ["This will teleport you to an area of the desert where you will need water to survive."] = "Esto te teletransportará a una zona del desierto donde necesitarás agua para sobrevivir.",
        ["Continue?"] = "¿Continuar?",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["No thanks."] = "No, gracias.",
        ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
        ["Who are you and what are you doing?"] = "¿Quién eres y qué estás haciendo?",
        ["We were once citizens of Menaphos but were exiled a long time ago."] = "Una vez fuimos ciudadanos de Menaphos pero fuimos exiliados hace mucho tiempo.",
        ["Now, we're attempting to seek forgiveness and gain re-entry to the great city. Perhaps you can help us..."] = "Ahora, estamos intentando buscar el perdón y lograr el reingreso a la gran ciudad. Quizás puedas ayudarnos...",
        ["I'll see what I can do."] = "Veré qué puedo hacer.",
    },
    ["Zamorak mage (Runecrafting Guild)"] = {
        ["Hello. That hat doesn't look like standard Zamorakian attire."] = "Hola. Ese sombrero no parece el atuendo estándar de Zamorak.",
        ["Shh! They haven't noticed me here yet."] = "¡Shh! Aún no me han notado aquí.",
        ["Why are you here? If they catch you here, they will kill you!"] = "¿Por qué estás aquí? ¡Si te atrapan aquí, te matarán!",
        ["Well, the runecrafting wizards have got themselves into a bit of a state over a thesis published by a student."] = "Bueno, los magos creadores de runas se han puesto un poco nerviosos por una tesis publicada por un estudiante.",
        ["We're also researching a new branch of Runecrafting at the moment: weapon imbuing."] = "También estamos investigando una nueva rama de Runecrafting en este momento: imbuir armas.",
        ["Select an Option"] = "Selecciona una opción",
        ["What did this paper say?"] = "¿Qué decía este documento?",
        ["Well, in short, it states that one day the altars like this one could run out of runic energy!"] = "Bueno, en resumen, ¡dice que algún día los altares como este podrían quedarse sin energía rúnica!",
        ["That's terrible! How will humans perform magic if we cannot make runes?"] = "¡Eso es terrible! ¿Cómo harán los humanos magia si no podemos hacer runas?",
        ["Well, it is only a theory. Hardly any of the Runecrafting Guild wizards believe it to be true."] = "Bueno, es sólo una teoría. Casi ninguno de los magos de Runecrafting Guild cree que esto sea cierto.",
        ["Still, we have not proved Wizard Finix's theories to be incorrect yet, and - if they're true - this is very worrying. Wizards have been dispatched to all the known altars to investigate."] = "Aún así, no hemos demostrado que las teorías de Wizard Finix sean incorrectas y, si son ciertas, esto es muy preocupante. Se han enviado magos a todos los altares conocidos para investigar.",
        ["So, what can we do if Wizard Finix's theories are true?"] = "Entonces, ¿qué podemos hacer si las teorías de Wizard Finix son ciertas?",
        ["Well, there is a new method being explored, which was detailed in Wizard Finix's thesis. He is the best person to explain it to you; he is currently in the Wizards' Tower, if you want to speak to him."] = "Bueno, se está explorando un nuevo método, que se detalló en la tesis de Wizard Finix. Él es la mejor persona para explicártelo; Actualmente está en Wizards' Tower, si quieres hablar con él.",
        ["Travel to the Wizards' Tower?"] = "¿Viaja al Wizards' Tower?",
        ["Yes"] = "si",
        ["What is weapon imbuing?"] = "¿Qué es la imbución de armas?",
        ["Well, if you bring an inert magic weapon to an altar, you can use rune essence to imbue the weapon instead of binding runes."] = "Bueno, si llevas un arma mágica inerte a un altar, puedes usar esencia rúnica para imbuir el arma en lugar de vincular runas.",
        ["This process saturates the weapon with runic energy and thus increases its power. This way, even regular wood can be made into menacing magical armaments!"] = "Este proceso satura el arma con energía rúnica y así aumenta su poder. ¡De esta manera, incluso la madera normal puede convertirse en amenazadores armamentos mágicos!",
        ["In theory, that is. During our studies, we only ever managed to imbue eternal magic wood, perhaps due to the strong inherent magical properties that it possesses."] = "En teoría, claro. Durante nuestros estudios, sólo logramos imbuir madera mágica eterna, tal vez debido a las fuertes propiedades mágicas inherentes que posee.",
        ["Our fellow wizards aren't proficient enough to properly imbue the wood either. None were able to get more than trace amounts of runic energy to settle in it."] = "Nuestros compañeros magos tampoco son lo suficientemente competentes para imbuir adecuadamente la madera. Ninguno pudo conseguir que más que pequeñas cantidades de energía rúnica se asentaran en él.",
        ["This altar here also doesn't seem to work for imbuing at all."] = "Este altar aquí tampoco parece funcionar para imbuir en absoluto.",
        ["I saw some Zamorakians try it and it looks like they only had any luck with fully imbued weapons, which dissipated into runic energy whenever they tried to imbue them any further."] = "Vi a algunos zamorakianos intentarlo y parece que solo tuvieron suerte con armas completamente imbuidas, que se disipaban en energía rúnica cada vez que intentaban imbuirlas más.",
        ["I have a theory that certain objects of abyssal origin may yield the same results."] = "Tengo la teoría de que ciertos objetos de origen abisal pueden producir los mismos resultados.",
        ["Maybe you should try it for yourself and see if you can get any use out of that effect."] = "Tal vez deberías probarlo tú mismo y ver si puedes sacarle algún provecho a ese efecto.",
        ["I'm too scared to attempt it myself."] = "Tengo demasiado miedo para intentarlo yo mismo.",
    },
    ["Zamorak mage"] = {
        ["Hello. That hat doesn't look like standard Zamorakian attire."] = "Hola. Ese sombrero no parece el atuendo estándar de Zamorak.",
        ["Shh! They haven't noticed me here yet."] = "¡Shh! Aún no me han notado aquí.",
        ["Why are you here? If they catch you here, they will kill you!"] = "¿Por qué estás aquí? ¡Si te atrapan aquí, te matarán!",
        ["Well, the runecrafting wizards have got themselves into a bit of a state over a thesis published by a student."] = "Bueno, los magos creadores de runas se han puesto un poco nerviosos por una tesis publicada por un estudiante.",
        ["We're also researching a new branch of Runecrafting at the moment: weapon imbuing."] = "También estamos investigando una nueva rama de Runecrafting en este momento: imbuir armas.",
        ["Select an Option"] = "Selecciona una opción",
        ["What did this paper say?"] = "¿Qué decía este documento?",
        ["Well, in short, it states that one day the altars like this one could run out of runic energy!"] = "Bueno, en resumen, ¡dice que algún día los altares como este podrían quedarse sin energía rúnica!",
        ["That's terrible! How will humans perform magic if we cannot make runes?"] = "¡Eso es terrible! ¿Cómo harán los humanos magia si no podemos hacer runas?",
        ["Well, it is only a theory. Hardly any of the Runecrafting Guild wizards believe it to be true."] = "Bueno, es sólo una teoría. Casi ninguno de los magos de Runecrafting Guild cree que esto sea cierto.",
        ["Still, we have not proved Wizard Finix's theories to be incorrect yet, and - if they're true - this is very worrying. Wizards have been dispatched to all the known altars to investigate."] = "Aún así, no hemos demostrado que las teorías de Wizard Finix sean incorrectas y, si son ciertas, esto es muy preocupante. Se han enviado magos a todos los altares conocidos para investigar.",
        ["So, what can we do if Wizard Finix's theories are true?"] = "Entonces, ¿qué podemos hacer si las teorías de Wizard Finix son ciertas?",
        ["Well, there is a new method being explored, which was detailed in Wizard Finix's thesis. He is the best person to explain it to you; he is currently in the Wizards' Tower, if you want to speak to him."] = "Bueno, se está explorando un nuevo método, que se detalló en la tesis de Wizard Finix. Él es la mejor persona para explicártelo; Actualmente está en Wizards' Tower, si quieres hablar con él.",
        ["Travel to the Wizards' Tower?"] = "¿Viaja al Wizards' Tower?",
        ["Yes"] = "si",
        ["What is weapon imbuing?"] = "¿Qué es la imbución de armas?",
        ["Well, if you bring an inert magic weapon to an altar, you can use rune essence to imbue the weapon instead of binding runes."] = "Bueno, si llevas un arma mágica inerte a un altar, puedes usar esencia rúnica para imbuir el arma en lugar de vincular runas.",
        ["This process saturates the weapon with runic energy and thus increases its power. This way, even regular wood can be made into menacing magical armaments!"] = "Este proceso satura el arma con energía rúnica y así aumenta su poder. ¡De esta manera, incluso la madera normal puede convertirse en amenazadores armamentos mágicos!",
        ["In theory, that is. During our studies, we only ever managed to imbue eternal magic wood, perhaps due to the strong inherent magical properties that it possesses."] = "En teoría, claro. Durante nuestros estudios, sólo logramos imbuir madera mágica eterna, tal vez debido a las fuertes propiedades mágicas inherentes que posee.",
        ["Our fellow wizards aren't proficient enough to properly imbue the wood either. None were able to get more than trace amounts of runic energy to settle in it."] = "Nuestros compañeros magos tampoco son lo suficientemente competentes para imbuir adecuadamente la madera. Ninguno pudo conseguir que más que pequeñas cantidades de energía rúnica se asentaran en él.",
        ["This altar here also doesn't seem to work for imbuing at all."] = "Este altar aquí tampoco parece funcionar para imbuir en absoluto.",
        ["I saw some Zamorakians try it and it looks like they only had any luck with fully imbued weapons, which dissipated into runic energy whenever they tried to imbue them any further."] = "Vi a algunos zamorakianos intentarlo y parece que solo tuvieron suerte con armas completamente imbuidas, que se disipaban en energía rúnica cada vez que intentaban imbuirlas más.",
        ["I have a theory that certain objects of abyssal origin may yield the same results."] = "Tengo la teoría de que ciertos objetos de origen abisal pueden producir los mismos resultados.",
        ["Maybe you should try it for yourself and see if you can get any use out of that effect."] = "Tal vez deberías probarlo tú mismo y ver si puedes sacarle algún provecho a ese efecto.",
        ["I'm too scared to attempt it myself."] = "Tengo demasiado miedo para intentarlo yo mismo.",
    },
    ["Zamorak, Lord of Chaos"] = {
        ["As you restore the Edict, Zamorak draws the remaining power from the rune, draining it and enrages."] = "A medida que restauras el Edicto, Zamorak extrae el poder restante de la runa, lo drena y se enfurece.",
        ["Zamorak enters a stage of rage... Drawing upon the power of the corrupt edicts."] = "Zamorak entra en una etapa de ira... Aprovechando el poder de los edictos corruptos.",
        ["Zamorak begins to draw power and energy from something within Infernus."] = "Zamorak comienza a extraer poder y energía de algo dentro de Infernus.",
        ["Zamorak's connection is currently too strong to the runes. You'll need to find a way to break the connection."] = "Actualmente, la conexión de Zamorak con las runas es demasiado fuerte. Necesitarás encontrar una manera de romper la conexión.",
        ["Your highest Zamorak enrage has increased by [number], bringing your highest achieved enrage to [number] for solo encounters."] = "Tu enojo máximo Zamorak ha aumentado en [número], lo que lleva tu enojo más alto alcanzado a [número] para encuentros en solitario.",
        ["Congratulations. You have completed the Elite Dungeon: The Zamorakian Undercity."] = "Felicitaciones. Has completado Elite Dungeon: The Zamorakian Undercity.",
        ["You have killed [number] Zamorak, Lord of Chaos in solo mode."] = "Has matado a [número] Zamorak, Lord of Chaos en modo solitario.",
        ["You are awarded [number] Marks of War and now have a total of [number]. You can earn [number] more before War is satisfied."] = "Se le otorgan marcas [número] de War y ahora tiene un total de [número]. Puede ganar [número] más antes de que War esté satisfecho.",
        ["A Chaos Demon is fixated on you. Watch out!"] = "Un Demonio del Caos está obsesionado contigo. ¡Cuidado!",
        ["Zamorak begins to conjure a world ending attack."] = "Zamorak comienza a conjurar un ataque que acabará con el mundo.",
        ["Zamorak's connection is weakened!"] = "¡La conexión de Zamorak está debilitada!",
        ["You sever Zamorak's connection completely! Strike now!"] = "¡Cortaste completamente la conexión de Zamorak! ¡Ataque ahora!",
        ["*One of the following is said*"] = "*Se dice una de las siguientes*",
        ["*Starting*"] = "*Empezando*",
        ["*Player's death*"] = "*Muerte de Player*",
        ["*Returning to the fight after dying*"] = "*Regresando a la pelea después de morir*",
        ["*Banishing Zamorak*"] = "*Desterrando a Zamorak*",
        ["*Last Stand*"] = "*Última batalla*",
        ["*Infernal Tomb*"] = "*Tumba Infernal*",
        ["*Starting with the Fractured Staff of Armadyl equipped*"] = "*Comenzando con el Staff fracturado o Armadyl equipado*",
        ["*Starting with Vestments of havoc armour equipped*"] = "*Comenzando con Vestimentas de armadura de caos equipadas*",
        ["*Uncategorised or Unknown*"] = "*Sin categoría o Desconocido*",
    },
    ["Zamorak"] = {
        ["Cower before me mortal! Bwahahahahaaa!"] = "¡Encoge de miedo ante mí, mortal! ¡Bwahahahahaaa!",
        ["Is that what you're expecting? Does the 'god of evil' match your expectations? Am I terrifying to behold? Truth to be told I do not consider evil a worthwhile pursuit, but neither do I consider it relevant. It is a term given by the closed-minded to label a world in shades of black and white, right and wrong. But you and I both know that the world is more than that. It isn't black and white, nor even shades of grey. Morality, like the world, is a myriad of colours in a vast array of shades and hues. My philosophy is 'strength from chaos and adversity'. It is about improving oneself by overcoming obstacles. The other gods would have you follow static rules and live a life as unchanging as stone. My way is better."] = "¿Es eso lo que esperabas? ¿El 'dios del mal' coincide con tus expectativas? ¿Soy aterrador de contemplar? La verdad es que no considero que el mal sea una búsqueda que valga la pena, pero tampoco lo considero relevante. Es un término dado por personas de mente cerrada para etiquetar un mundo en tonos de blanco y negro, lo correcto y lo incorrecto. Pero tú y yo sabemos que el mundo es más que eso. No es blanco y negro, ni siquiera tonos de gris. La moralidad, como el mundo, es una miríada de colores en una amplia gama de matices y matices. Mi filosofía es \"la fuerza del caos y la adversidad\". Se trata de superarse a uno mismo superando obstáculos. Los otros dioses te harían seguir reglas estáticas y vivir una vida tan inmutable como la piedra. Mi camino es mejor.",
        ["So why have you appeared here now?"] = "Entonces, ¿por qué has aparecido aquí ahora?",
        ["Because something is coming. I feel the strands of fate tightening around the world. twisting and knotting. trapping us all. I hear laughter in the shadows... I have heard that laughter before and it rarely ends well."] = "Porque algo viene. Siento que los hilos del destino se tensan en todo el mundo. retorciéndose y anudándose. atrapándonos a todos. Escucho risas en las sombras... He escuchado esa risa antes y rara vez termina bien.",
        ["Hello World Guardian. Forgive me for this rather dramatic scene, sometimes you need a bit of theatre to get people's attention. Theatre is something that Sliske has always been rather good at. Even this 'game' of his, it is set during an eclipse. A 'once in a mortal lifetime' event. It's the perfect disguise."] = "Hola guardián del mundo. Perdónenme por esta escena bastante dramática, a veces hace falta un poco de teatro para llamar la atención de la gente. El teatro es algo en lo que Sliske siempre ha sido bastante bueno. Incluso este 'juego' suyo está ambientado durante un eclipse. Un evento \"único en la vida de un mortal\". Es el disfraz perfecto.",
        ["Disguise for what?"] = "¿Disfraz de qué?",
        ["With Sliske everything is always disguised. He pitches this as a game, but it is no less than an arms race of godly proportions. Someone will win the stone; the most powerful device in existence. The other gods will not just sit back and allow that. So we are all gathering. All preparing for the final confrontation. Even though we know it may mean our deaths."] = "Con Sliske todo siempre está disfrazado. Lo presenta como un juego, pero no es menos que una carrera armamentista de proporciones divinas. Alguien ganará la piedra; el dispositivo más potente que existe. Los otros dioses no se quedarán sentados y permitirán eso. Entonces nos estamos reuniendo todos. Todos preparándose para el enfrentamiento final. Aunque sabemos que puede significar nuestra muerte.",
        ["Welcome, Player. What brings you to me at this hour?"] = "Bienvenido, Player. ¿Qué te trae a mí a esta hora?",
        ["Can you talk about Sliske's game?"] = "¿Puedes hablar sobre el juego de Sliske?",
        ["What is there to say? Sliske is dead and the stone is gone. Good riddance on both accounts."] = "¿Qué hay que decir? Sliske está muerto y la piedra ha desaparecido. Buen viaje en ambas cuentas.",
        ["What do you think about..."] = "¿Qué piensas sobre...?",
        ["**Zamorak** Ah yes, Armadyl, seeker of justice and would-be unifier of the gods. If foolishness could be given a face, it would be his. The gods will never work together, not really. Each of us has our own agenda, our own ideologies and they blend together like oil and fire. Does he really believe that Saradomin and myself could ever be anything more than mortal enemies? Of course he doesn't. Which means he will have to pick a side and history has already shown me that he will not choose my side. So he must see me as a threat and we both know what he does to threats. But I am not Bandos. My battles will not be fought by strength alone. There are rules to warfare and I will win because I will not play by them, whereas Armadyl will be forced to. I love fighting a foe with a code of honour. It's like I've already won."] = "**Zamorak** Ah, sí, Armadyl, buscador de justicia y aspirante a unificador de los dioses. Si a la tontería se le pudiera poner un rostro, sería el suyo. Los dioses nunca trabajarán juntos, en realidad no. Cada uno de nosotros tiene su propia agenda, nuestras propias ideologías y se mezclan como el aceite y el fuego. ¿Realmente cree que Saradomin y yo podríamos ser algo más que enemigos mortales? Por supuesto que no. Lo que significa que tendrá que elegir un bando y la historia ya me ha demostrado que no elegirá mi bando. Entonces debe verme como una amenaza y ambos sabemos lo que hace con las amenazas. Pero no soy Bandos. Mis batallas no se librarán sólo con la fuerza. Hay reglas para la guerra y yo ganaré porque no las seguiré, mientras que Armadyl se verá obligado a hacerlo. Me encanta luchar contra un enemigo con un código de honor. Es como si ya hubiera ganado.",
        ["**Zamorak** Do you really need to ask my opinion on that hypocrite? Saradomin would see the universe as his great empire. Everyone trapped in roles he has chosen them. What he preaches to his followers is nothing more than a life of moral slavery. He would see free will crushed and removed and his will raised above all. Yet it is I who is painted as evil. I feel sorry for his followers, I truly do, they do not see that they are forging their own chains and shackling us all."] = "**Zamorak** ¿Realmente necesitas pedirme mi opinión sobre ese hipócrita? Saradomin vería el universo como su gran imperio. Cada uno atrapado en roles que él los ha elegido. Lo que predica a sus seguidores no es más que una vida de esclavitud moral. Vería el libre albedrío aplastado y eliminado y su voluntad elevada por encima de todo. Sin embargo, soy yo quien es retratado como malvado. Lo siento por sus seguidores, de verdad, no ven que están forjando sus propias cadenas y encadenándonos a todos.",
        ["**Zamorak** No. Those wounds are still too fresh, too raw. Even thinking about what she did, it fills me with an uncontrollable rage and I would rather not level Edgeville in my fury."] = "**Zamorak** No. Esas heridas todavía están demasiado frescas, demasiado abiertas. Incluso pensar en lo que hizo, me llena de una rabia incontrolable y preferiría no nivelar a Edgeville en mi furia.",
        ["**Zamorak** Sliske cannot be trusted. Even Sliske doesn't trust Sliske. Yet here we all are, all forced to play his little game because the situation he has created for us, it's the perfect trap. I'll give Sliske that compliment, he's a master strategist, if a twisted one. Even his intrigues have intrigues. He is a mahjarrat wearing many masks, I wounder if he knows where the masks end and he begins?"] = "**Zamorak** No se puede confiar en Sliske. Incluso Sliske no confía en Sliske. Sin embargo, aquí estamos todos, todos obligados a jugar su pequeño juego porque la situación que él ha creado para nosotros es la trampa perfecta. Le haré ese cumplido a Sliske, es un maestro estratega, aunque retorcido. Incluso sus intrigas tienen intrigas. Es un mahjarrat que lleva muchas máscaras, me pregunto si sabe dónde terminan las máscaras y dónde comienza él.",
        ["**Zamorak** In many ways Zaros is as complicit as Seren in the fate of the mahjarrat and I do hate him for that, make no mistake there. But you know that I am bound to aid him in Sliske's game. I do not know how, I do not know when, but I know it will be an act that will cost me greatly. My only comfort is knowing that I am surely not the only one pinioned in this way. Zaros never puts all his eggs in one basket."] = "**Zamorak** En muchos sentidos, Zaros es tan cómplice como Seren en el destino del mahjarrat y lo odio por eso, no se equivoque. Pero sabes que estoy obligado a ayudarlo en el juego de Sliske. No sé cómo, no sé cuándo, pero sé que será un acto que me costará mucho. Mi único consuelo es saber que seguramente no soy el único atado de esta manera. Zaros nunca pone todos sus huevos en la misma canasta.",
        ["**Zamorak** Icthlarin may not be the strongest of the gods, but he is not one to count out of any race. I have seen him lead armies, back when we were his 'Stern Judges'. I have found myself wondering of late, 'what if'. What if we had never betrayed Icthlarin, what if we had sided with him against Zaros. What could have been? I would never have become a god, I would never have been able to save my people, by Sliske might never have had a chance to take the stone for himself. Makes you think. How one action can affect the world so greatly. On this I have based my philosophy and it holds truer each day."] = "**Zamorak** Puede que Icthlarin no sea el más fuerte de los dioses, pero no es alguien que deba excluirse de ninguna raza. Lo he visto liderar ejércitos, cuando éramos sus 'Jueces severos'. Últimamente me he preguntado: \"¿Y si?\". ¿Y si nunca hubiéramos traicionado a Icthlarin, y si nos hubiéramos puesto del lado de él contra Zaros? ¿Qué pudo haber sido? Nunca me habría convertido en un dios, nunca habría podido salvar a mi pueblo, por Sliske tal vez nunca hubiera tenido la oportunidad de tomar la piedra para sí mismo. Te hace pensar. Cómo una acción puede afectar tanto al mundo. En esto he basado mi filosofía y cada día es más cierta.",
        ["Death"] = "Muerte",
        ["**Zamorak** Death is an important function, so Death himself performs an important role. As a person, I barely know him and I doubt the two of us are going to be having drinks together anytime soon."] = "**Zamorak** La muerte es una función importante, por lo que la propia muerte desempeña un papel importante. Como persona, apenas lo conozco y dudo que los dos vayamos a tomar unas copas juntos pronto.",
        ["The dragonkin"] = "los dragonantes",
        ["**Zamorak** The dragonkin are dangerous. Never, ever forget that. However reasonable some of them may seen, history teaches us that they will stop at nothing to destroy us all. My advice. Next time you find one injured, kill it. Don't hesitate. Don't listen to its pleas. Strike it down or it will end up destroying you. I know there is one in Daemonheim somewhere. My agents hear whispers. They are planning something to do with 'the echo's link', whatever that means. My agents also believe that they have got their hands on one of the elder artefacts. So whatever they are doing, it cannot be good."] = "**Zamorak** Los dragonantes son peligrosos. Nunca, jamás olvides eso. Por muy razonables que algunos de ellos puedan parecer, la historia nos enseña que no se detendrán ante nada para destruirnos a todos. Mi consejo. La próxima vez que encuentres a uno herido, mátalo. No lo dudes. No escuches sus súplicas. Derribalo o terminará destruyéndote. Sé que hay uno en Daemonheim en alguna parte. Mis agentes escuchan susurros. Están planeando algo que tenga que ver con \"el enlace del eco\", sea lo que sea que eso signifique. Mis agentes también creen que han conseguido uno de los artefactos más antiguos. Entonces, hagan lo que hagan, no puede ser bueno.",
        ["**Zamorak** Honestly I have little to say about Vorago. I know he is a powerful beast that guards the anima, but beyond that I have no further opinion."] = "**Zamorak** Sinceramente tengo poco que decir sobre Vorago. Sé que es una bestia poderosa que guarda el ánima, pero más allá de eso no tengo más opinión.",
        ["**Zamorak** It is easy to dismiss Brassica Prime, as a joke, or as irrelevant. But just because something is strange, it does not mean it should be ignored. Brassica was able to convince Guthix to leave him behind when the edicts came up. Even Seren was not able to do this. He is certainly not as powerful as he claims to be. But if his boasts are to be believed, his agents are fruits and vegetables everywhere. Laugh at that for a moment and then stop and think. Are there any kings who do not have such things in their kitchens and then served at their diplomatic banquets? Even the gods discuss their plans within earshot of assorted plant matter. So what secrets must Brassica really know? If knowledge is power, he must really be a force to consider carefully. He's a fool, yes, a joke, certainly. But what better mask is there?"] = "**Zamorak** Es fácil descartar Brassica Prime, como una broma o como irrelevante. Pero sólo porque algo sea extraño no significa que deba ignorarse. Brassica pudo convencer a Guthix de que lo dejara atrás cuando surgieron los edictos. Ni siquiera Seren pudo hacer esto. Ciertamente no es tan poderoso como dice ser. Pero si hay que creer en sus alardes, sus agentes son frutas y verduras en todas partes. Ríase de eso por un momento y luego deténgase y piense. ¿Hay reyes que no tengan tales cosas en sus cocinas y luego las sirvan en sus banquetes diplomáticos? Incluso los dioses discuten sus planes al alcance del oído de una variedad de materia vegetal. Entonces, ¿qué secretos debe conocer realmente Brassica? Si el conocimiento es poder, en realidad debe ser una fuerza a considerar cuidadosamente. Es un tonto, sí, un chiste, sin duda. ¿Pero qué mejor máscara hay?",
        ["**Zamorak** I'd...er...rather not talk about her. Just...well just don't let yourself be alone with her in a room for a long period of time. She bites!"] = "**Zamorak** Yo... eh... preferiría no hablar de ella. Sólo... bueno, no te dejes estar solo con ella en una habitación por un largo período de tiempo. ¡Muerde!",
    },
    ["Zamorakian diviner"] = {
        ["You hand in: [number] x Displaced energy."] = "Entregas: [número] x Energía desplazada.",
        ["They're so pretty, aren't they? I'm not allowed near the energy in the crater so this is as close as I'll get."] = "Son muy bonitos, ¿no? No se me permite acercarme a la energía en el cráter, así que esto es lo más cerca que podré llegar.",
        ["You have one little tiny explosive accident with a transmutation spell and nobody trusts you any more."] = "Tienes un pequeño accidente explosivo con un hechizo de transmutación y ya nadie confía en ti.",
        ["Anyway. This energy source will run out soon. Gather as much as you can before it vanishes."] = "De todos modos. Esta fuente de energía se agotará pronto. Reúne todo lo que puedas antes de que desaparezca.",
        ["For completing this event you receive: 1 x Sack of wild rewards."] = "Por completar este evento recibirás: 1 x Saco de recompensas salvajes.",
    },
    ["Zamorakian fanatic (Battle of Lumbridge)"] = {
        ["Aha! I see a new recruit for the army of Zamorak."] = "¡Ajá! Veo un nuevo recluta para el ejército de Zamorak.",
        ["Yes! Where do I sign up?"] = "¡Sí! ¿Dónde me registro?",
        ["I knew it! You should go to the south side of the battlefield in Lumbridge, and talk to the officer there."] = "¡Lo sabía! Debes ir al lado sur del campo de batalla en Lumbridge y hablar con el oficial que se encuentra allí.",
        ["You can sign up, and fight for the winning side - ours!"] = "Puedes registrarte y luchar por el bando ganador: ¡el nuestro!",
        ["And if you don't want to fight, we also need skilled gatherers of all types."] = "Y si no quieres pelear, también necesitamos recolectores expertos de todo tipo.",
        ["Don't delay. We need all the help we can get!"] = "No te demores. ¡Necesitamos toda la ayuda que podamos conseguir!",
        ["Maybe. Why would I join you?"] = "Quizás. ¿Por qué me uniría a ti?",
        ["Because we're the strongest!"] = "¡Porque somos los más fuertes!",
        ["Zamorak is the most powerful of the gods, and soon Saradomin will fall before our might. You can be part of that victory."] = "Zamorak es el más poderoso de los dioses, y pronto Saradomin caerá ante nuestro poder. Tú puedes ser parte de esa victoria.",
        ["Everyone can play a part, from the weakest to the strongest, and from the warrior to the woodcutter. All welcome!"] = "Todos pueden participar, desde el más débil hasta el más fuerte, y desde el guerrero hasta el leñador. ¡Todos bienvenidos!",
        ["To join us, you need to go to the south side of the battlefield in Lumbridge and talk to the recruiter."] = "Para unirte a nosotros, debes ir al lado sur del campo de batalla en Lumbridge y hablar con el reclutador.",
        ["I'm on my way!"] = "¡Estoy en camino!",
        ["Praise be to Zamorak! I look forward to the day we defeat Saradomin!"] = "¡Alabado sea Zamorak! ¡Espero con ansias el día en que derrotemos a Saradomin!",
        ["No way! I support Saradomin!"] = "¡De ninguna manera! ¡Apoyo a Saradomin!",
        ["You would side with the weak and worthless Saradomin? Then I pity you."] = "¿Te pondrías del lado del débil e inútil Saradomin? Entonces te compadezco.",
        ["But it is not too late for you to join the winning side. Zamorak is all-powerful, and soon all of Gielinor will see!"] = "Pero aún no es demasiado tarde para unirte al bando ganador. Zamorak es todopoderoso, ¡y pronto todos los Gielinor lo verán!",
        ["I don't want to get involved."] = "No quiero involucrarme.",
        ["You are uninterested? This battle will touch everyone."] = "¿No estás interesado? Esta batalla tocará a todos.",
        ["And when Zamorak is victorious, it will be too late for you to seek scraps from his table."] = "Y cuando Zamorak salga victorioso, será demasiado tarde para que busques las sobras de su mesa.",
        ["It's not over yet! You can still join the mighty Zamorak, if you head to the south side of the battlefield."] = "¡Aún no ha terminado! Aún puedes unirte al poderoso Zamorak si te diriges al lado sur del campo de batalla.",
        ["I see you have already joined the winning side! Go back to the battlefield at Lumbridge!"] = "¡Veo que ya te has unido al bando ganador! ¡Vuelve al campo de batalla en Lumbridge!",
        ["I should strike you down where you stand, follower of Saradomin. Begone before I lose my temper."] = "Debería derribarte donde estás, seguidor de Saradomin. Vete antes de que pierda los estribos.",
    },
    ["Zamorakian fanatic"] = {
        ["Aha! I see a new recruit for the army of Zamorak."] = "¡Ajá! Veo un nuevo recluta para el ejército de Zamorak.",
        ["Yes! Where do I sign up?"] = "¡Sí! ¿Dónde me registro?",
        ["I knew it! You should go to the south side of the battlefield in Lumbridge, and talk to the officer there."] = "¡Lo sabía! Debes ir al lado sur del campo de batalla en Lumbridge y hablar con el oficial que se encuentra allí.",
        ["You can sign up, and fight for the winning side - ours!"] = "Puedes registrarte y luchar por el bando ganador: ¡el nuestro!",
        ["And if you don't want to fight, we also need skilled gatherers of all types."] = "Y si no quieres pelear, también necesitamos recolectores expertos de todo tipo.",
        ["Don't delay. We need all the help we can get!"] = "No te demores. ¡Necesitamos toda la ayuda que podamos conseguir!",
        ["Maybe. Why would I join you?"] = "Quizás. ¿Por qué me uniría a ti?",
        ["Because we're the strongest!"] = "¡Porque somos los más fuertes!",
        ["Zamorak is the most powerful of the gods, and soon Saradomin will fall before our might. You can be part of that victory."] = "Zamorak es el más poderoso de los dioses, y pronto Saradomin caerá ante nuestro poder. Tú puedes ser parte de esa victoria.",
        ["Everyone can play a part, from the weakest to the strongest, and from the warrior to the woodcutter. All welcome!"] = "Todos pueden participar, desde el más débil hasta el más fuerte, y desde el guerrero hasta el leñador. ¡Todos bienvenidos!",
        ["To join us, you need to go to the south side of the battlefield in Lumbridge and talk to the recruiter."] = "Para unirte a nosotros, debes ir al lado sur del campo de batalla en Lumbridge y hablar con el reclutador.",
        ["I'm on my way!"] = "¡Estoy en camino!",
        ["Praise be to Zamorak! I look forward to the day we defeat Saradomin!"] = "¡Alabado sea Zamorak! ¡Espero con ansias el día en que derrotemos a Saradomin!",
        ["No way! I support Saradomin!"] = "¡De ninguna manera! ¡Apoyo a Saradomin!",
        ["You would side with the weak and worthless Saradomin? Then I pity you."] = "¿Te pondrías del lado del débil e inútil Saradomin? Entonces te compadezco.",
        ["But it is not too late for you to join the winning side. Zamorak is all-powerful, and soon all of Gielinor will see!"] = "Pero aún no es demasiado tarde para unirte al bando ganador. Zamorak es todopoderoso, ¡y pronto todos los Gielinor lo verán!",
        ["I don't want to get involved."] = "No quiero involucrarme.",
        ["You are uninterested? This battle will touch everyone."] = "¿No estás interesado? Esta batalla tocará a todos.",
        ["And when Zamorak is victorious, it will be too late for you to seek scraps from his table."] = "Y cuando Zamorak salga victorioso, será demasiado tarde para que busques las sobras de su mesa.",
        ["It's not over yet! You can still join the mighty Zamorak, if you head to the south side of the battlefield."] = "¡Aún no ha terminado! Aún puedes unirte al poderoso Zamorak si te diriges al lado sur del campo de batalla.",
        ["I see you have already joined the winning side! Go back to the battlefield at Lumbridge!"] = "¡Veo que ya te has unido al bando ganador! ¡Vuelve al campo de batalla en Lumbridge!",
        ["I should strike you down where you stand, follower of Saradomin. Begone before I lose my temper."] = "Debería derribarte donde estás, seguidor de Saradomin. Vete antes de que pierda los estribos.",
    },
    ["Zamorakian herbalist (female)"] = {
        ["Our son loves it here! He is always playing around near that trapdoor."] = "¡A nuestro hijo le encanta estar aquí! Siempre está jugando cerca de esa trampilla.",
    },
    ["Zamorakian herbalist"] = {
        ["Our son loves it here! He is always playing around near that trapdoor."] = "¡A nuestro hijo le encanta estar aquí! Siempre está jugando cerca de esa trampilla.",
    },
    ["Zamorakian herbalist (male)"] = {
        ["Ever since we've moved again things keep going missing and that awful trapdoor outside keeps creaking in the night!"] = "Desde que nos mudamos de nuevo, siguen desapareciendo cosas y esa horrible trampilla de afuera sigue crujiendo en la noche.",
    },
    ["Zamorakian miner"] = {
        ["You hand in: [number] x Strange ore."] = "Entregas: [número] x Mineral extraño.",
        ["The miner is muttering to themselves under their mask. You hear something about 'unusual rocks' and 'ore' and something extremely rude about lazy smiths.<br>He seems to want you to gather ore for him."] = "El minero murmura para sí mismo bajo su máscara. Escuchas algo sobre \"rocas inusuales\" y \"mineral\" y algo extremadamente grosero sobre los herreros perezosos. <br>Parece querer que recolectes mineral para él.",
        ["For completing this event you receive: 1 x Sack of wild rewards."] = "Por completar este evento recibirás: 1 x Saco de recompensas salvajes.",
    },
    ["Zanaris choir"] = {
        ["What do you want? We're trying to sing! Leave us alone and we won't bother you!"] = "¿Qué quieres? ¡Estamos intentando cantar! ¡Déjanos en paz y no te molestaremos!",
        ["Dialogue 1"] = "Diálogo 1",
        ["Dialogue 2"] = "Diálogo 2",
        ["Dialogue 3"] = "Diálogo 3",
        ["Dialogue 4"] = "Diálogo 4",
        ["Dialogue 5"] = "Diálogo 5",
        ["Dialogue 6"] = "Diálogo 6",
    },
    ["Zandar Horfyre"] = {
        ["Who are you?"] = "¿Quién eres?",
        ["My name is Zandar Horfyre. You, Player, are trespassing in my tower, not to mention attacking my students! I thank you to leave immediately!"] = "Mi nombre es Zandar Horfyre. ¡Tú, Player, estás invadiendo mi torre, sin mencionar que estás atacando a mis alumnos! ¡Te agradezco que te vayas inmediatamente!",
        ["Select an option"] = "Seleccione una opción",
        ["Okay, I was going anyway."] = "Está bien, iba a ir de todos modos.",
        ["Good! And don't forget to close the door behind you!"] = "¡Bien! ¡Y no olvides cerrar la puerta detrás de ti!",
        ["No, I think I'll stay for a bit."] = "No, creo que me quedaré un rato.",
        ["Actually, that wasn't an invitation. I've tried being polite, now we'll do it the hard way!"] = "En realidad, eso no fue una invitación. He intentado ser cortés, ¡ahora lo haremos de la manera más difícil!",
        ["Zamorak curse that mage! Actually, I guess he already has!"] = "Zamorak ¡Maldito sea ese mago! En realidad, ¡supongo que ya lo ha hecho!",
    },
    ["Zanik"] = {
        ["Hello, Player!"] = "¡Hola, Player!",
        ["**Player:{{anchor|story}}** Hello, Zanik! What have you been up to?"] = "**Player:{{anchor|story}}** ¡Hola, Zanik! ¿Qué has estado haciendo?",
        ["A giant frog found its way into the mines, but I helped the guards to drive it off!"] = "Una rana gigante llegó a las minas, ¡pero ayudé a los guardias a ahuyentarla!",
        ["It got away in the end. But it was the biggest I'd ever seen!"] = "Al final se nos escapó. ¡Pero era el más grande que jamás había visto!",
        ["I've been thinking about my destiny..."] = "He estado pensando en mi destino...",
        ["What was it Juna said to me? 'Your destiny is to lead all goblins into a new age."] = "¿Qué fue lo que me dijo Juna? \"Tu destino es llevar a todos los duendes a una nueva era\".",
        ["All goblins.' Not just the Dorgeshuun, all goblins..."] = "Todos los duendes'. No sólo los Dorgeshuun, todos los duendes...",
        ["And what does it even mean, my destiny? Is it something I'm certain to do, or just something I ought to do? How can I know?"] = "¿Y qué significa eso de mi destino? ¿Es algo que estoy seguro de hacer o simplemente algo que debería hacer? ¿Cómo puedo saberlo?",
        ["I talked to Juna about it, but she wouldn't tell me anything. She just said, 'You will know, when the time is right."] = "Hablé con Juna al respecto, pero ella no me dijo nada. Ella simplemente dijo: 'Lo sabrás cuando sea el momento adecuado'.",
        ["I've been helping Oldak with his experiments!"] = "¡He estado ayudando a Oldak con sus experimentos!",
        ["I took his magic ball all over the caves and even to Lumbridge to test what happened when I broke it, and I always ended up back here."] = "Llevé su bola mágica por todas las cuevas e incluso a Lumbridge para probar qué pasaba cuando la rompía, y siempre terminaba de regreso aquí.",
        ["You might find one of those balls useful if you wanted to visit me! Perhaps you should talk to Oldak."] = "¡Quizás una de esas bolas te resulte útil si quisieras visitarme! Quizás deberías hablar con Oldak.",
        ["I went on another visit to Lumbridge! I still can't convince other Dorgeshuun to go to the surface with me, though."] = "¡Hice otra visita a Lumbridge! Aunque todavía no puedo convencer a otros Dorgeshuun para que vayan a la superficie conmigo.",
        ["You've still got that ancient mace... It must be my imagination, but I can almost feel the power coming off it, like it's calling out to me. You should keep it safe, Player!"] = "Todavía tienes esa maza antigua... Debe ser mi imaginación, pero casi puedo sentir el poder que emana de ella, como si me estuviera llamando. ¡Deberías mantenerlo a salvo, Player!",
        ["I thought you had the ancient goblin mace, Player. But I found it in the caves. When I picked it up I felt strange... it was as if someone was watching to me, urging me to do something, but I don't know what! I gave it to Tegdak. If you want to have it again you should talk to him."] = "Pensé que tenías la antigua maza de duende, Player. Pero lo encontré en las cuevas. Cuando lo cogí me sentí raro... era como si alguien me estuviera mirando, instándome a hacer algo, ¡pero no sé qué! Se lo di a Tegdak. Si quieres volver a tenerlo debes hablar con él.",
        ["I visited the goblin village again. I wanted to learn more about their legend of the 'Chosen Commander'. But I didn't find out any more. They couldn't decide whether I really was the chosen commander or not, and they just got into a big argument about it."] = "Visité la aldea de los duendes nuevamente. Quería aprender más sobre la leyenda del 'Comandante Elegido'. Pero no descubrí más. No pudieron decidir si realmente yo era el comandante elegido o no, y simplemente tuvieron una gran discusión al respecto.",
        ["Zanik, the council is still very concerned about the city's safety. If you hear of any more H.A.M. activity on the surface, you must let me know."] = "Zanik, el ayuntamiento sigue muy preocupado por la seguridad de la ciudad. Si oye hablar de más H.A.M. actividad en la superficie, debes hacérmelo saber.",
        ["Don't worry, I'm sure Player will help keep us safe from the H.A.M people!"] = "¡No te preocupes, estoy seguro de que Player nos ayudará a mantenernos a salvo de la gente de H.A.M!",
        ["And another thing. If you must visit the surface, the council asks that you be careful not to offend the surface-dwellers' customs."] = "Y otra cosa. Si debes visitar la superficie, el consejo te pide que tengas cuidado de no ofender las costumbres de los habitantes de la superficie.",
        ["Of course, I'll be careful."] = "Por supuesto, tendré cuidado.",
        ["Remember in particular to scrupulously observe the Lumbridge-Dorgeshuun treaty..."] = "Recuerde en particular respetar escrupulosamente el tratado Lumbridge-Dorgeshuun...",
        ["Alright!"] = "¡Muy bien!",
        ["Oh, hello, Player!"] = "¡Oh, hola, Player!",
        ["How are your studies going, Oldak?"] = "¿Cómo van tus estudios, Oldak?",
        ["Oh! Zanik! It's fascinating. These 'runes' store a type of energy I've never encountered before."] = "¡Oh! ¡Zanik! Es fascinante. Estas 'runas' almacenan un tipo de energía que nunca antes había encontrado.",
        ["Really?"] = "¿En serio?",
        ["Yes. Each type of rune has its power tuned to a different effect, but they are all essentially the same energy. What I want to know is where this energy came from. The stone that these runes were cut from must be infused with an enormous amount of raw magical energy, but where did that energy come from?"] = "Sí. Cada tipo de runa tiene su poder sintonizado para un efecto diferente, pero todas son esencialmente la misma energía. Lo que quiero saber es de dónde vino esta energía. La piedra de la que se cortaron estas runas debe estar imbuida de una enorme cantidad de energía mágica pura, pero ¿de dónde vino esa energía?",
        ["Maybe someday we'll find out! Oh, hello, Player!"] = "¡Quizás algún día lo descubramos! ¡Hola, Player!",
        ["*This dialogue is available as a dialogue option in all locations.*"] = "*Este diálogo está disponible como opción de diálogo en todas las ubicaciones.*",
        ["About Bandos..."] = "Acerca de Bandos...",
        ["Bandos is dead! Armadyl killed him - and it's thanks to you!"] = "¡Bandos está muerto! Armadyl lo mató, ¡y es gracias a ti!",
        ["It's thanks to me?"] = "¿Es gracias a mí?",
        ["His old plan was to stay out of danger and lead his forces via a puppet avatar. But we destroyed the pendant he used to control his avatar, so when the way opened for him to come back, he had to come in person or not at all."] = "Su antiguo plan era mantenerse fuera de peligro y liderar sus fuerzas a través de un avatar títere. Pero destruimos el colgante que usaba para controlar su avatar, así que cuando se le abrió el camino para regresar, tuvo que venir en persona o no hacerlo.",
        ["Destroying the pendant also weakened him, more than he realised. He thought he was more powerful than Armadyl, but we brought him down to the same level."] = "Destruir el colgante también lo debilitó, más de lo que pensaba. Pensó que era más poderoso que Armadyl, pero lo bajamos al mismo nivel.",
        ["Most importantly, though, we made him angry. He was defeated, not just by another god, but by mortals, and that hurt him more than you can imagine. I don't think he was capable of backing down after that."] = "Pero lo más importante es que lo hicimos enojar. Fue derrotado, no sólo por otro dios, sino por mortales, y eso le dolió más de lo que puedas imaginar. No creo que fuera capaz de dar marcha atrás después de eso.",
        ["Will goblins go back to Yu'biusk?"] = "¿Volverán los duendes a Yu'biusk?",
        ["There's nothing for us there. Yu'biusk is dead; nothing will ever grow there again."] = "Allí no hay nada para nosotros. Yu'biusk está muerto; Nada volverá a crecer allí.",
        ["Gielinor is our home now. We'll just have to get along with all the other races here."] = "Gielinor es nuestro hogar ahora. Tendremos que llevarnos bien con todas las demás razas aquí.",
        ["You must be happy now Bandos is gone for good."] = "Debes estar feliz ahora que Bandos se ha ido para siempre.",
        ["I...I wouldn't tell most people this but since it's you..."] = "Yo... Yo no le diría esto a la mayoría de la gente, pero como eres tú...",
        ["I still have nightmares, sometimes, about being controlled. I'll think I'm the Chosen Commander again, leading an army of goblins and killing all these people."] = "A veces todavía tengo pesadillas en las que me controlan. Pensaré que soy el Comandante Elegido otra vez, liderando un ejército de duendes y matando a toda esta gente.",
        ["But than I wake up and remember it's not real, and I'm fine. Than I think about the whole world out there and all the adventures I can go on, and I'm fine. Really, I'm fine."] = "Pero luego me despierto y recuerdo que no es real, y estoy bien. Luego pienso en el mundo entero y en todas las aventuras que puedo vivir, y estoy bien. De verdad, estoy bien.",
        ["What are you doing in the Sixth Age?"] = "¿Qué estás haciendo en la Sexta Edad?",
        ["I joined the Godless as soon as I heard Holstein's speech."] = "Me uní a Godless tan pronto como escuché el discurso de Holstein.",
        ["All types of mortals under a common banner, standing together against the gods! It's inspiring! Like when the two of us faced Bandos, but on a global scale!"] = "¡Todo tipo de mortales bajo un estandarte común, unidos contra los dioses! ¡Es inspirador! Como cuando nos enfrentamos los dos a Bandos, ¡pero a escala global!",
        ["But now...I'm not even sure what the Godless are doing. Kara-Meir stood by while two gods nearly destroyed Lumbridge, and again at Falador. I begged her to join Armadyl's side against Bandos, but she wouldn't listen."] = "Pero ahora... ni siquiera estoy seguro de qué están haciendo los Godless. Kara-Meir se mantuvo al margen mientras dos dioses casi destruyen a Lumbridge, y nuevamente a Falador. Le rogué que se uniera al lado de Armadyl contra Bandos, pero ella no me escuchó.",
        ["But we have no chance against the gods unless we work together, and the Godless are still our best shot at that. I guess I'll have to see what happens."] = "Pero no tenemos ninguna posibilidad contra los dioses a menos que trabajemos juntos, y los Sin Dios siguen siendo nuestra mejor oportunidad para lograrlo. Supongo que tendré que ver qué pasa.",
        ["Goodbye."] = "Adiós.",
        ["Goodbye, Player. See you soon."] = "Adiós, Player. Nos vemos pronto.",
        ["Oh, Player, lets not talk about that now its all over."] = "Oh, Player, no hablemos de eso ahora que todo terminó.",
        ["But is he really gone?"] = "¿Pero realmente se ha ido?",
        ["As far as we can tell. He needed the pendant in order to control people, and with that destroyed, he can't do anything. Even if he comes back...well, we know how to fight him now. And besides...he won't come back. He was in my head, remember? I know how he thinks. He's been defeated, and not just by another god, but by mortals, and that hurts him more than you can imagine. He won't come back here and risk defeat again."] = "Hasta donde sabemos. Necesitaba el colgante para controlar a la gente, y con eso destruido, no puede hacer nada. Incluso si regresa... bueno, ahora sabemos cómo luchar contra él. Y además... no volverá. Estaba en mi cabeza, ¿recuerdas? Sé cómo piensa. Ha sido derrotado, y no sólo por otro dios, sino por mortales, y eso le duele más de lo que puedas imaginar. No volverá aquí y correrá el riesgo de ser derrotado otra vez.",
        ["There's nothing for us there. Yu'biusk is dead; nothing will ever grow there again. Gielinor is our home now. We'll just have to get along with all the other races here."] = "No hay nada para nosotros allí. Yu'biusk está muerto; Nada volverá a crecer allí. Gielinor es nuestro hogar ahora. Tendremos que llevarnos bien con todas las demás razas aquí.",
        ["How do you feel about it?"] = "¿Cómo te sientes al respecto?",
        ["Hello, Player."] = "Hola, Player.",
        ["*(Same as above)*"] = "*(Igual que arriba)*",
        ["What have you been up to?"] = "¿Qué has estado haciendo?",
        ["I crossed the river into Morytania; the whole land was so gloomy and depressing. There was a whole castle full of strange creatures, and a swamp… I found this nice little town… Or at least I thought it was nice… But when I was in the bar I accidentally spilt someone’s drink, and they all turned into wolf-men!"] = "Crucé el río hacia Morytania; toda la tierra era tan lúgubre y deprimente. Había todo un castillo lleno de criaturas extrañas y un pantano... Encontré este bonito pueblecito... O al menos pensé que era bonito... Pero cuando estaba en el bar, accidentalmente derramé la bebida de alguien, ¡y todos se convirtieron en hombres lobo!",
        ["I spent some time in Keldagrim. Some of the people were nice, but I didn’t like the city so much. Everything was so industrial and it was all controlled by corporations. I ended up hanging out with this dwarf who ate a lot of kebabs. I don’t quite remember what happened after that. I think I got a bit drunk!"] = "Pasé algún tiempo en Keldagrim. Algunas personas eran agradables, pero a mí no me gustaba tanto la ciudad. Todo era muy industrial y todo estaba controlado por corporaciones. Terminé saliendo con este enano que comía muchos kebabs. No recuerdo muy bien qué pasó después de eso. ¡Creo que me emborraché un poco!",
        ["I went and talked to Juna again, but she wouldn’t talk to me. She still says I should have helped Bandos take over Dorgesh-Kaan. She says I had no right to go against my ‘destiny’. She thinks that gods should always get what they want, just because they’re gods, and that mortals just don’t matter. I didn’t realise she thought such hateful things. We used to be such good friends… Back when the city was still cut off, I used to sit with her for hours, listening to her stories of the surface and just imagining what it was like. I can see the surface for myself now, but still, I’m going to miss that."] = "Fui y hablé con Juna nuevamente, pero ella no quiso hablar conmigo. Ella todavía dice que debería haber ayudado a Bandos a hacerse cargo de Dorgesh-Kaan. Ella dice que no tenía derecho a ir en contra de mi \"destino\". Ella piensa que los dioses siempre deberían conseguir lo que quieren, sólo porque son dioses, y que los mortales simplemente no importan. No me di cuenta de que ella pensaba cosas tan odiosas. Solíamos ser tan buenos amigos… Cuando la ciudad todavía estaba aislada, solía sentarme con ella durante horas, escuchando sus historias sobre la superficie e imaginando cómo era. Ahora puedo ver la superficie por mí mismo, pero aún así, lo voy a extrañar.",
        ["I visited Varrock the other day. It’s such a huge city, isn’t it? Even bigger than home! There were so many people! I met a gypsy who said she could foresee the future, but she couldn’t see mine!"] = "Visité Varrock el otro día. Es una ciudad tan grande, ¿no? ¡Incluso más grande que casa! ¡Había tanta gente! Conocí a una gitana que decía que podía prever el futuro, ¡pero no podía ver el mío!",
        ["I visited the Kharidian Desert. I’ve never seen such a big expanse of empty ground! After growing up in these confined caves, it was amazing! Just the yellow ground and the blue sky, and me in the middle. I found a ruined city where there was a man made out of clay. He said he was left over from the God Wars and he said you had repaired him."] = "Visité el Kharidian Desert. ¡Nunca había visto una extensión de terreno tan grande y vacía! Después de crecer en estas cuevas confinadas, ¡fue increíble! Sólo el suelo amarillo y el cielo azul, y yo en el medio. Encontré una ciudad en ruinas donde había un hombre hecho de barro. Dijo que era un resto de las Guerras de Dios y que tú lo habías reparado.",
        ["Goodbye Player. See you soon."] = "Adiós Player. Nos vemos pronto.",
        ["Player! You're a member of the Champion's Guild too? This is great!"] = "¡Player! ¿También eres miembro del Gremio de Campeones? ¡Esto es genial!",
        ["How did you become a member of the guild?"] = "¿Cómo te convertiste en miembro del gremio?",
        ["I had to do a quest to prove myself. I had to slay a monsterbut the monster was the easy part! The hard part was getting there; everyone had lost the map."] = "Tuve que hacer una búsqueda para demostrar mi valía. Tuve que matar a un monstruo, ¡pero el monstruo fue la parte fácil! Lo difícil fue llegar allí; todos habían perdido el mapa.",
        ["What do you think of the guild?"] = "¿Qué opinas del gremio?",
        ["It's alright, but I wouldn't want to stay here long. The Guildmaster never goes out on adventures , he just stands and greets people. The champions downstairs aren't much better. They asked me to be the 'Cave Goblin Champion but I wasn't interested. I don't want to spend all my time sitting and waiting for excitement to come to me. I want to get out there and find it!"] = "Está bien, pero no me gustaría quedarme aquí mucho tiempo. El Guildmaster nunca sale de aventuras, simplemente se para y saluda a la gente. Los campeones de abajo no son mucho mejores. Me pidieron que fuera el 'Campeón Duende de las Cavernas pero no estaba interesado. No quiero pasar todo el tiempo sentado esperando que me llegue la emoción. ¡Quiero salir y encontrarlo!",
        ["What are you working on, Oldak?"] = "¿En qué estás trabajando, Oldak?",
        ["Mmm...what? Oh, yes. Grubfoot and I are trying to break runes down into their smallest components. It's fascinating. It was Grubfoot's idea, really."] = "Mmm... ¿qué? Oh sí. Grubfoot y yo estamos intentando descomponer las runas en sus componentes más pequeños. Es fascinante. En realidad, fue idea de Grubfoot.",
        ["We smash runes together! Then we get bits!"] = "¡Aplastamos runas juntos! ¡Entonces obtenemos pedazos!",
        ["Yes, quite. Then we take those bits..."] = "Sí, bastante. Luego tomamos esos pedazos...",
        ["Then we smash bits together!"] = "¡Entonces aplastamos pedazos juntos!",
        ["Is it safe?"] = "¿Es seguro?",
        ["Oh, yes! There only very small chance we accidentally destroy world!"] = "¡Oh, sí! ¡Hay muy pocas posibilidades de que destruyamos el mundo accidentalmente!",
        ["Almost no chance at all, in fact."] = "De hecho, casi no hay ninguna posibilidad.",
        ["Well, that's a relief! Oh, hello, Player."] = "Bueno, ¡eso es un alivio! Hola, Player.",
        ["Can I help?"] = "¿Puedo ayudar?",
        ["Yes. We can both help."] = "Sí. Ambos podemos ayudar.",
        ["No, thank you. This is a very technical job and too many hands would just increase the chance of an accident."] = "No, gracias. Este es un trabajo muy técnico y demasiadas manos sólo aumentarían las posibilidades de sufrir un accidente.",
        ["Oh, well. See you later, Oldak!"] = "Oh, bueno. ¡Hasta luego, Oldak!",
        ["What are you doing here?"] = "¿Qué haces aquí?",
        ["I was just checking out Oldak's latest experiments."] = "Estaba revisando los últimos experimentos de Oldak.",
        ["Most of Oldak's magic goes over my head, but what little I do understand is fascinating. It's brilliant the way he tries everything out to see whether what he thinks is true or not."] = "La mayor parte de la magia de Oldak pasa por alto, pero lo poco que entiendo es fascinante. Es brillante la forma en que prueba todo para ver si lo que piensa es verdad o no.",
        ["You know, sometimes I think he likes it more when his theories turn out to be wrong. That way he gets to invent new theories to try out."] = "Sabes, a veces creo que le gusta más cuando sus teorías resultan estar equivocadas. De esa manera puede inventar nuevas teorías para probar.",
        ["So then what happened?"] = "Entonces, ¿qué pasó?",
        ["Why, then I looted its body, of course! Why else would I have slain the giant?"] = "¡Entonces saqueé su cuerpo, por supuesto! ¿Por qué si no habría matado al gigante?",
        ["I thought you were there to save the people of the village!"] = "¡Pensé que estabas allí para salvar a la gente del pueblo!",
        ["Oh, yes that too. When I got back they threw gave me lots of presents and we danced till the sun came up. Ah, those were the days."] = "Oh, sí, eso también. Cuando regresé me dieron muchos regalos y bailamos hasta que salió el sol. Ah, esos eran los días.",
        ["Oh hello Player, Dionysius was just telling me about his adventures."] = "Oh, hola Player, Dionysius justo me estaba contando sus aventuras.",
        ["What adventure is this?"] = "¿Qué aventura es esta?",
        ["Oh just a small tale of a giant I once killed, it's nothing special. I am far more interested in hearing of your adventures young Zanik, I have never met such an exceptional goblin."] = "Oh, solo una pequeña historia de un gigante que una vez maté, no es nada especial. Estoy mucho más interesado en escuchar tus aventuras, joven Zanik, nunca había conocido a un duende tan excepcional.",
        ["Well, Player and I did stop the H.A.M people from destroying my city."] = "Bueno, Player y yo evitamos que la gente H.A.M destruyera mi ciudad.",
        ["Opposition to monsters is very well, but those H.A.M. people can take things a bit too far."] = "La oposición a los monstruos está muy bien, pero esos H.A.M. la gente puede llevar las cosas demasiado lejos.",
        ["Yes, well then we were nearly conquered by an evil avatar of Bandos, but Player and I managed to defeat it."] = "Sí, bueno, entonces casi fuimos conquistados por un avatar malvado de Bandos, pero Player y yo logramos derrotarlo.",
        ["You defeated an evil god, you must have had Saradomin on your side to achieve such a thing!"] = "¡Derrotaste a un dios malvado, debes haber tenido a Saradomin de tu lado para lograr tal cosa!",
        ["Well no, we defeated him ourselves and we are getting on fine without any gods."] = "Bueno, no, lo derrotamos nosotros mismos y nos llevamos bien sin ningún dios.",
        ["Hmm. Well. A great adventure. Well done."] = "Mmm. Bien. Una gran aventura. Bien hecho.",
        ["What are you doing in Draynor?"] = "¿Qué estás haciendo en Draynor?",
        ["I was just exploring the human lands. I heard there was one old adventurer living here so I came to see what I could learn."] = "Estaba explorando las tierras humanas. Escuché que había un viejo aventurero viviendo aquí, así que vine para ver qué podía aprender.",
        ["A typical adventure. You fight one raggedy giant, then everyone treats you like you're special. Bah."] = "Una aventura típica. Luchas contra un gigante andrajoso y luego todos te tratan como si fueras especial. Bah.",
        ["Yes, dear. Don't worry, I don't do that sort of thing anymore."] = "Sí, querido. No te preocupes, ya no hago ese tipo de cosas.",
        ["It's nice to meet someone who sets out to solve their own problems instead of waiting for help from a passing adventurer."] = "Es agradable conocer a alguien que se propone resolver sus propios problemas en lugar de esperar la ayuda de un aventurero que pasa.",
        ["Well, I think we might have been defeated if it weren't for Player."] = "Bueno, creo que podríamos haber sido derrotados si no fuera por Player.",
        ["Oh, suit yourself."] = "Oh, haz lo que quieras.",
        ["Nevertheless, that was a great feat. Well done, well done."] = "Sin embargo, fue una gran hazaña. Bien hecho, bien hecho.",
        ["Hello."] = "Hola.",
        ["Look Wartface! It's Chosen Commander!"] = "¡Mira Cara de Verruga! ¡Es el comandante elegido!",
        ["I'm no-"] = "No estoy-",
        ["She not Chosen Commander!"] = "¡Ella no es la comandante elegida!",
        ["She is Chosen Commander!"] = "¡Ella es la comandante elegida!",
        ["She NOT Chosen Commander!"] = "¡Ella NO fue elegida comandante!",
        ["Wartface, at least listen to what she has to say."] = "Wartface, al menos escucha lo que tiene que decir.",
        ["Alright Dorgesh-Kaan goblin, me not think you chosen commander, but me listen to what you say."] = "Muy bien, duende Dorgesh-Kaan, no creo que hayas elegido comandante, pero escucho lo que dices.",
        ["So what you say Chosen Commander?"] = "Entonces, ¿qué dices Comandante Elegido?",
        ["I am not the Chosen Commander! Not anymore."] = "¡No soy el Comandante Elegido! Ya no.",
        ["Me tell you she not chosen commander you stupid Bentnoze!"] = "¡Te digo que ella no eligió comandante, estúpido Bentnoze!",
        ["Shut up Wartface, you stupid! You shut up too Not-Chosen-Commander, we not listen to you!"] = "¡Cállate Wartface, estúpido! ¡Cállate tú también, Comandante no elegido, no te escuchamos!",
        ["Suit yourself. Oh hello Player."] = "Haz lo que quieras. Hola Player.",
        ["Oh, Grubfoot asked me to see how the generals were doing. He's getting worried they can't cope without him."] = "Oh, Grubfoot me pidió que viera cómo estaban los generales. Le preocupa que no puedan arreglárselas sin él.",
        ["Grubfoot? Grubfoot in Dorgesh-Kaan City?"] = "¿Grubfoot? Grubfoot en la ciudad Dorgesh-Kaan?",
        ["You tell him to come back here now! We need him to do things."] = "¡Dile que vuelva aquí ahora! Necesitamos que él haga cosas.",
        ["Generals got to have servant. If we not have servant than we not proper generals!"] = "Los generales deben tener sirvientes. ¡Si no tenemos sirvientes, entonces no somos generales adecuados!",
        ["He doesn't want to come back, he's living in Dorgesh-Kaan now."] = "No quiere volver, ahora vive en Dorgesh-Kaan.",
        ["Well then, maybe you be our servant Not-Chosen-Commander!"] = "¡Bueno, entonces tal vez seas nuestro sirviente, Comandante No Elegido!",
        ["Yes! Not-Chosen-Commander, go get us dinner!"] = "¡Sí! Comandante no elegido, ¡ve a buscarnos la cena!",
        ["I am not going to be your servant!"] = "¡No voy a ser tu sirviente!",
        ["Shut up Not-Chosen-Commander! Where's that dinner?"] = "¡Cállate, comandante no elegido! ¿Dónde está esa cena?",
        ["Oh what's the point? Goodbye generals, nice talking to you."] = "Oh, ¿cuál es el punto? Adiós generales, un placer hablar con ustedes.",
        ["How do you get along with the surface goblins?"] = "¿Cómo te llevas con los duendes de la superficie?",
        ["Not too well; it's a pity. These are my people too you know, just as much as the cave goblins are. They're not bad people, Well a lot of them are, but not inherently evil. They are not as stupid as they look either. Some of them, like Grubfoot, are quite smart, but their god tells them thinking for themselves is wrong, so they don't. I should probably just leave them alone, I only start an argument when I show up here."] = "No muy bien; es una pena. Esta también es mi gente, ya sabes, tanto como lo son los duendes de las cavernas. No son malas personas, bueno, muchos de ellos lo son, pero no son inherentemente malvados. Tampoco son tan estúpidos como parecen. Algunos de ellos, como Grubfoot, son bastante inteligentes, pero su dios les dice que pensar por sí mismos está mal, así que no lo hacen. Probablemente debería dejarlos en paz, sólo comienzo una discusión cuando aparezco aquí.",
        ["So... can you impart your wise wisdom to me, O Oracle?"] = "Entonces... ¿puedes impartirme tu sabia sabiduría, O Oracle?",
        ["You? Ah! Do not touch me!"] = "¿Tú? ¡Ah! ¡No me toque!",
        ["What's the matter?"] = "¿Qué pasa?",
        ["You are adrift. A broken person, adrift in time, and all you touch is broken and lost... the gods play..."] = "Estás a la deriva. Una persona rota, a la deriva en el tiempo, y todo lo que tocas está roto y perdido... los dioses juegan...",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["The gods play games, but a playing piece leaves the board. The gods' play is acted out, and some say their lines and some forget, but you..."] = "Los dioses juegan, pero una pieza abandona el tablero. La obra de los dioses se representa, y algunos dicen sus líneas y otros las olvidan, pero tú...",
        ["There is the way it is, and the way it would have been but now never will be... and I can see both, and it hurts."] = "Así es como es, y como habría sido pero ahora nunca será... y puedo ver ambas cosas, y duele.",
        ["You are adrift - a hole in destiny. You have no destiny and... I cannot look at you."] = "Estás a la deriva: un agujero en el destino. No tienes destino y... no puedo mirarte.",
        ["No destiny. I think I can live with that."] = "Sin destino. Creo que puedo vivir con eso.",
        ["Oh, hello, Player."] = "Ah, hola, Player.",
        ["What was that about?"] = "¿De qué se trató eso?",
        ["Your guess is as good as mine... something about destiny. It looks like my destiny is messed up because of what we did."] = "Tu suposición es tan buena como la mía... algo sobre el destino. Parece que mi destino está arruinado por lo que hicimos.",
        ["Well, that's fine by me. 'Destiny' is just a fancy word for what some god wanted me to do. I don't want anything to do with that. My future is unwritten and I'll write it myself."] = "Bueno, por mí está bien. \"Destino\" es sólo una palabra elegante para lo que algún dios quería que hiciera. No quiero tener nada que ver con eso. Mi futuro no está escrito y lo escribiré yo mismo.",
        ["Oh, someone told me the Oracle could see the future, so I thought that was worth checking out... but never mind that."] = "Oh, alguien me dijo que el Oracle podía ver el futuro, así que pensé que valía la pena echarle un vistazo... pero eso no importa.",
        ["The view here is amazing - I can see so far. This must be the highest place I've been."] = "La vista aquí es increíble, puedo ver hasta ahora. Este debe ser el lugar más alto en el que he estado.",
        ["And snow! I'd never even imagined it before I saw it on the surface."] = "¡Y nieve! Ni siquiera lo había imaginado antes de verlo en la superficie.",
        ["You know, you can keep your destiny and your predictions. I've got a good feeling about my future."] = "Ya sabes, puedes conservar tu destino y tus predicciones. Tengo un buen presentimiento sobre mi futuro.",
        ["Hello Player, isn't it beautiful here? It's so peaceful!"] = "Hola Player, ¿no es hermoso aquí? ¡Es tan pacífico!",
        ["Yes, I like it."] = "Sí, me gusta.",
        ["I am glad you like it too. Most of the humans here pass through so quickly. They don't stop to look around."] = "Me alegra que a ti también te guste. La mayoría de los humanos aquí pasan muy rápido. No se detienen a mirar a su alrededor.",
        ["It's full of mud and ogres!"] = "¡Está lleno de barro y ogros!",
        ["Its full of mud and ogres!"] = "¡Está lleno de barro y ogros!",
        ["And? What's wrong with mud and ogres? Oh, never mind. I think it's something humans don't appreciate so much."] = "¿Y? ¿Qué hay de malo con el barro y los ogros? Ah, no importa. Creo que es algo que los humanos no aprecian tanto.",
        ["I think this place is especially peaceful for goblins and ogres and other...you know...other Bandos races. Races from Yu'biusk."] = "Creo que este lugar es especialmente pacífico para los duendes, ogros y otras... ya sabes... otras razas de Bandos. Carreras de Yu'biusk.",
        ["I think that this place must be like Yu'biusk. Not like it is now, but like it was before Bandos destroyed it. Mud, plants, cool water - it's just like Grubfoot described."] = "Creo que este lugar debe ser como Yu'biusk. No como es ahora, sino como era antes de que Bandos lo destruyera. Barro, plantas, agua fría: es tal como lo describió Grubfoot.",
        ["So it moves something deep inside us. It feels like home."] = "Entonces mueve algo muy dentro de nosotros. Se siente como en casa.",
        ["I'll show these stuck up archers, I'll show 'em all!"] = "¡Les mostraré a estos arqueros engreídos, les mostraré a todos!",
        ["What are you doing in the Ranging Guild?"] = "¿Qué estás haciendo en el Ranging Guild?",
        ["I am going to prove myself! I am going for the record! They made fun of me, they said crossbows weren't as good as \"real\" bows! Well they won't be laughing when I hold the ranging competition record!"] = "¡Voy a demostrar mi valía! ¡Voy por el récord! ¡Se burlaron de mí, dijeron que las ballestas no eran tan buenas como los arcos \"reales\"! ¡Bueno, no se reirán cuando tenga el récord de la competencia de alcance!",
        ["What do you think of the Ranging Guild?"] = "¿Qué opinas del Ranging Guild?",
        ["Would you believe they wouldn't let me in at first? They said a goblin would never make a decent archer. Well I showed them... with seven bullseyes in a row! A goblin with a crossbow is more fancy than their longbows and throwing axes any day!"] = "¿Creerías que al principio no me dejaron entrar? Dijeron que un duende nunca sería un arquero decente. Bueno, se los mostré... ¡con siete dianas seguidas! ¡Un duende con una ballesta es más elegante que sus arcos largos y hachas arrojadizas!",
        ["Well, I wanted to check out these mystics that people have talked about, and their portal to another world."] = "Bueno, quería ver a estos místicos de los que la gente ha hablado y su portal a otro mundo.",
        ["They won't let me go through their portal to see the other world, though. The Head Mystic talked about how the holy ones were angry with me or something."] = "Sin embargo, no me dejan pasar por su portal para ver el otro mundo. El Head Mystic habló de cómo los santos estaban enojados conmigo o algo así.",
        ["Well, never mind, there's plenty to see in this world."] = "Bueno, no importa, hay mucho que ver en este mundo.",
        ["What do you think of the mystics?"] = "¿Qué opinas de los místicos?",
        ["They worship the ghosts in the wilderness - ghosts left over from the God Wars. Did you realise that?"] = "Adoran a los fantasmas en wilderness, fantasmas que quedaron de las Guerras de Dios. ¿Te diste cuenta de eso?",
        ["They seem to think the God Wars was a time of glorious battles, where everyone was heroic and brave. I think if they could, they'd go back to that time...or they'd start a new war here."] = "Parecen pensar que las Guerras de Dios fueron una época de batallas gloriosas, donde todos eran heroicos y valientes. Creo que si pudieran, regresarían a esa época... o comenzarían una nueva guerra aquí.",
        ["I know a bit about war - I've had the War God in my head, after all - and I don't think these mystics would be so fascinated by war if they were in a real one."] = "Sé un poco sobre la guerra; después de todo, he tenido al Dios War en mi cabeza, y no creo que estos místicos estarían tan fascinados por la guerra si estuvieran en una real.",
        ["Hello, Player. I didn't think I'd run into you so far from home."] = "Hola, Player. No pensé que me encontraría contigo tan lejos de casa.",
        ["Or maybe I should call you... JalYt - something-or-other - Player."] = "O tal vez debería llamarte... JalYt - algo u otro - Player.",
        ["I am JalYt-Xil-Zanik!"] = "¡Soy JalYt-Xil-Zanik!",
        ["What are you doing in Tz-Haar?"] = "¿Qué estás haciendo en Tz-Haar?",
        ["I have been fighting in the fight caves, i haven't gotten to the end yet though. They say there's some huge creature called TzTok-Jad."] = "He estado peleando en las cuevas de lucha, aunque aún no he llegado al final. Dicen que hay una criatura enorme llamada TzTok-Jad.",
        ["I have reached TzTok-Jad."] = "He llegado a TzTok-Jad.",
        ["You have, what's it like? Wait, wait don't tell me. I am gonna find out for myself!"] = "Tienes, ¿cómo es? Espera, espera, no me digas. ¡Lo descubriré por mí mismo!",
        ["I haven't reached Tz-Tok-Jad either."] = "Yo tampoco he llegado a Tz-Tok-Jad.",
        ["Well we'll see who gets to him first. Ha, ha ha!"] = "Bueno, veremos quién llega a él primero. ¡Ja, ja, ja!",
        ["What do you think of the TzHaar?"] = "¿Qué opinas del TzHaar?",
        ["It's fascinating. It's an underground city, but it's totally different from home."] = "Es fascinante. Es una ciudad subterránea, pero es totalmente diferente de casa.",
        ["Even though I grew up in Dorgesh-Kaan, I can see how it's an artificial place. Goblins are from the surface originally, just like humans. The underground is a hostile environment and we have to came it."] = "Aunque crecí en Dorgesh-Kaan, puedo ver que es un lugar artificial. Los duendes son originalmente de la superficie, al igual que los humanos. El underground es un entorno hostil y tenemos que salir de él.",
        ["But these Tzhaar... they belong underground. They're creatures of rock and fire, born out of the volcano, so a city down here is totally natural for them."] = "Pero estos Tzhaar... pertenecen al subsuelo. Son criaturas de roca y fuego, nacidas del volcán, por lo que una ciudad aquí abajo es totalmente natural para ellos.",
        ["Oh, hello, Player..."] = "Oh, hola, Player...",
        ["So you're a wizard now?"] = "¿Entonces ahora eres un mago?",
        ["Oh, no. some of the wizards tried to teach me magic, but I just don't have the knack."] = "Oh, no. Algunos de los magos intentaron enseñarme magia, pero simplemente no tengo la habilidad.",
        ["I couldn't even cast Wind Strike, and they say everyone can cast that."] = "Ni siquiera pude lanzar Wind Strike, y dicen que todos pueden lanzar eso.",
        ["What do you think of the Wizards' Tower?"] = "¿Qué opinas del Wizards' Tower?",
        ["It's interesting. I don't understand the first thing about magic, but it's still interesting."] = "Es interesante. No entiendo nada sobre magia, pero sigue siendo interesante.",
        ["They handle it so differently from how Oldak does. He's just trying things out on his own. Sometimes they work, but more often they don't and he tries something else."] = "Lo manejan de manera muy diferente a como lo hace Oldak. Simplemente está probando cosas por su cuenta. A veces funcionan, pero más a menudo no funcionan y él intenta otra cosa.",
        ["Here, the wizards have hundreds of years of tradition to draw upon. They can do so much more than Oldak... but I get the impression they don't really understand what they're doing, some of the time."] = "Aquí, los magos tienen cientos de años de tradición a los que recurrir. Pueden hacer mucho más que Oldak... pero tengo la impresión de que algunas veces no entienden realmente lo que están haciendo.",
        ["Well, I came here to get some books for Oldak. He's been in touch with some of the wizards here through letters, so I wanted to see what this place was like for myself."] = "Bueno, vine aquí para conseguir algunos libros para Oldak. Ha estado en contacto con algunos de los magos aquí a través de cartas, así que quería ver cómo era este lugar por mí mismo.",
        ["Then, when I got here, old Wizard Traiborn asked to look for something called a 'thingummywut'. I looked all over but I couldn't find it. I'm starting to think it doesn't exist."] = "Luego, cuando llegué aquí, el viejo Wizard Traiborn me pidió buscar algo llamado 'thingummywut'. Busqué por todas partes pero no pude encontrarlo. Estoy empezando a pensar que no existe.",
        ["There's no such thing as Thingummywuts; Wizard Traiborn is mad."] = "No existen los Thingummywuts; Wizard Traiborn está enojado.",
        ["Haha! I thought as much."] = "¡Jaja! Eso pensé.",
        ["The Thingummywut is definitely around here somewhere."] = "El Thingummywut definitivamente está por aquí en alguna parte.",
        ["Oh, well, I'll keep looking then."] = "Oh, bueno, seguiré buscando entonces.",
        ["Hello?"] = "¿Hola?",
        ["Player? Where are you? I can’t see you in the swamp."] = "¿Player? ¿Dónde estás? No puedo verte en el pantano.",
        ["I’m contacting you by magic!"] = "¡Me estoy contactando contigo por arte de magia!",
        ["I’m exploring Morytania and… Woah! I’m slipping! Wo-o-oah!"] = "Estoy explorando Morytania y… ¡Guau! ¡Me estoy resbalando! ¡Guau!",
        ["Zanik? Are you alright?"] = "¿Zanik? ¿Estás bien?",
        ["I’ve fallen in the swamp! What should I do, Player?"] = "¡Me caí en el pantano! ¿Qué debo hacer, Player?",
        ["Grapple out with your crossbow!"] = "¡Enfréntate con tu ballesta!",
        ["Okay, I’ll try that… There, the grapple’s caught on a tree. I’m climbing out… I’ve landed in a bush, and… Hey, there’s someone else here! Hey! Lumberjack! Over here! He’s turning this way, and… Oh. Uh-oh. I think he’s a zombie."] = "Está bien, lo intentaré... Ahí, el garfio está atrapado en un árbol. Estoy saliendo... He aterrizado en un arbusto, y... ¡Oye, hay alguien más aquí! ¡Ey! ¡Leñador! ¡Por aquí! Él está girando hacia aquí y... Oh. Oh, oh. Creo que es un zombi.",
        ["Run for it!"] = "¡Corre!",
        ["You don’t need to tell me twice! Ha ha ha! Zombies can’t run! Phew! I’ve lost him! I think I can see the wall of the temple here. I’m out of the swamp. Thanks for the help, Player. See you later!"] = "¡No es necesario que me lo digas dos veces! ¡Ja, ja, ja! ¡Los zombis no pueden correr! ¡Uf! ¡Lo he perdido! Creo que puedo ver el muro del templo aquí. Estoy fuera del pantano. Gracias por la ayuda, Player. ¡Hasta luego!",
        ["You can take it! Fight!"] = "¡Puedes aceptarlo! ¡Luchar!",
        ["It’s not so tough! Its arm's come off, but it's still coming at me! Now, I’ve cut off both its arms, but it’s still trying to bite me! What? It’s hopping at me on one leg! Why doesn’t it die already? There. I’ve cut off all its limbs and kicked it in the swamp. No zombie is safe from Zanik of the Dorgeshuun! I don’t think I’ll have trouble with anything else in this swamp. Thanks for the help, Player! See you around!"] = "¡No es tan difícil! ¡Se le ha caído el brazo, pero todavía viene hacia mí! Ahora le he cortado ambos brazos, ¡pero todavía intenta morderme! ¿Qué? ¡Está saltando hacia mí en una pierna! ¿Por qué no muere ya? Allá. Le corté todas las extremidades y lo pateé al pantano. ¡Ningún zombi está a salvo de Zanik de Dorgeshuun! No creo que tenga problemas con nada más en este pantano. ¡Gracias por la ayuda, Player! ¡Ya nos veremos!",
        ["Try to swim to the bank!"] = "¡Intenta nadar hasta la orilla!",
        ["I think I can do that! The bank is just… Hey, what’s that? There’s a head poking out of the water… Eek! Tentacles! It’s got me!"] = "¡Creo que puedo hacer eso! El banco simplemente... Oye, ¿qué es eso? Hay una cabeza asomando del agua… ¡Eek! Tentáculos! ¡Me tiene!",
        ["Attack the tentacle!"] = "¡Attack el tentáculo!",
        ["If I can just reach my dagger… It’s working! It doesn’t like that at all! Phew! It let me go. I’m back on the bank now. I’m not badly hurt, but I’m covered in swamp slime and monster blood. I’m going to stop here and try to clean it off. Thanks for your help, Player. I’ll talk to you some other time."] = "Si pudiera alcanzar mi dagger... ¡Está funcionando! ¡Eso no le gusta nada! ¡Uf! Me dejó ir. Ya estoy de vuelta en el banco. No estoy gravemente herido, pero estoy cubierto de baba de pantano y sangre de monstruo. Voy a parar aquí y tratar de limpiarlo. Gracias por tu ayuda, Player. Te hablaré en otro momento.",
        ["Attack the head!"] = "¡Attack la cabeza!",
        ["I hope my crossbow’s still dry enough… Haha! Got it! Crossbow bolt in the eye! It didn’t seem to hurt it too much, but it’s let me go. I’ve got back to the bank. I think I can see a way out of the swamp from here. Thanks for your help, Player! I’ll talk to you some other time."] = "Espero que mi ballesta todavía esté lo suficientemente seca... ¡Jaja! ¡Entiendo! ¡Perno de ballesta en el ojo! No pareció dolerme demasiado, pero me dejó ir. He vuelto al banco. Creo que puedo ver una salida del pantano desde aquí. ¡Gracias por tu ayuda, Player! Te hablaré en otro momento.",
        ["Hey, Player, do you know someone called Evil Dave? He’s telling me about his plan for world domination, but I’m not sure if he’s being serious."] = "Hola, Player, ¿conoces a alguien llamado Evil Dave? Me está contando sobre su plan para dominar el mundo, pero no estoy seguro de si habla en serio.",
        ["He’s an evil wizard! You’ve got to stop him!"] = "¡Es un mago malvado! ¡Tienes que detenerlo!",
        ["Okay, I’ve got this. Stop right now, Evil Dave! If you want to conquer the world, you’ll have to get past me first! He’s casting a spell, Player! He’s made a magic circle and he’s going to summon something! I have to disrupt the magic somehow!"] = "Bien, ya lo tengo. ¡Detente ahora mismo, Evil Dave! ¡Si quieres conquistar el mundo, primero tendrás que superarme! ¡Está lanzando un hechizo, Player! ¡Ha hecho un círculo mágico y va a invocar algo! ¡Tengo que interrumpir la magia de alguna manera!",
        ["Make him get the words wrong!"] = "¡Haz que se equivoque de palabras!",
        ["Abracadabra! Oogle-boogle, shazam! That’s confused him. He’s made a mistake. Something’s appearing… It’s …A cabbage? Oh. Evil Dave is taking it up to his mum to make into dinner. I think he’s given up his evil plans for now."] = "¡Abracadabra! ¡Oogle-boogle, shazam! Eso lo confunde. Ha cometido un error. Algo está apareciendo... Es... ¿Un repollo? Oh. Evil Dave se lo llevará a su madre para preparar la cena. Creo que por ahora ha abandonado sus malvados planes.",
        ["Disrupt the magic circle!"] = "¡Interrumpe el círculo mágico!",
        ["There! The circle’s broken! Something is still happening, though… Evil Dave has turned himself into a fish! He’s flopping around and- Oh, he’s turned back. He says he’s going to go and have a lie down. I think his evil plans are foiled for the time being."] = "¡Ahí! ¡El círculo se ha roto! Sin embargo, algo todavía está sucediendo... ¡Evil Dave se ha convertido en un pez! Está dando vueltas y... Oh, se ha dado la vuelta. Dice que va a ir a acostarse. Creo que sus malvados planes se han frustrado por el momento.",
        ["Just let him cast the spell."] = "Déjalo lanzar el hechizo.",
        ["Well, okay. He’s finished the spell. Something’s emerging… It’s a rat! A little red rat with glowing eyes! Aww, it’s cute. It’s eating some cheese out of my hand. Evil Dave is so disappointed. He says he was sure he’d get it right this time."] = "Bueno, está bien. Ha terminado el hechizo. Algo está surgiendo… ¡Es una rata! ¡Una pequeña rata roja con ojos brillantes! Vaya, es lindo. Está comiendo un poco de queso de mi mano. Evil Dave está muy decepcionado. Dice que estaba seguro de que esta vez lo haría bien.",
        ["I think he’s harmless."] = "Creo que es inofensivo.",
        ["Really? He’s asking me to join his evil scheme. He says I could be his ‘Evil Death-Bringer Assassin of Darkness’."] = "¿En serio? Me está pidiendo que me una a su malvado plan. Dice que yo podría ser su \"Asesino de la Oscuridad portador de la muerte malvado\".",
        ["You’d make a great assassin of darkness."] = "Serías un gran asesino de la oscuridad.",
        ["Ha! I bet I would. I’d stand on a rooftop, wrapped in a black cloak, a crossbow bolt glinting in the moonlight as my target moved unsuspecting below… Um, if I were evil, of course. Which I’m not. I think I’ve hung around with Evil Dave long enough. I’ll talk to you some other time, Player."] = "¡Ja! Apuesto que lo haría. Me pararía en un tejado, envuelto en una capa negra, una ballesta brillando a la luz de la luna mientras mi objetivo se movía desprevenido abajo... Um, si fuera malvado, por supuesto. Lo cual no lo soy. Creo que ya llevo bastante tiempo con Evil Dave. Te hablaré en otro momento, Player.",
        ["You’re not going to join him, are you?"] = "No vas a unirte a él, ¿verdad?",
        ["Of course not. You won’t catch me being part of any evil scheme! Well, except that one time, of course. But I don’t want to talk about that. Anyway, I think I should leave Evil Dave to his schemes. I’ll see you around, Player."] = "Por supuesto que no. ¡No me pillarás siendo parte de ningún plan malvado! Bueno, excepto esa vez, por supuesto. Pero no quiero hablar de eso. De todos modos, creo que debería dejar a Evil Dave con sus planes. Nos vemos por ahí, Player.",
        ["Player? Oldak, something’s happening. I’ve got Player in my head."] = "¿Player? Oldak, algo está pasando. Tengo Player en mi cabeza.",
        ["Um, okay. Hey, Player, do you know what an “abyssal doom vortex” is? Because that’s what Oldak says he’s created in his lab. It’s kind of getting larger. I think it’s going to explode."] = "Mmm, está bien. Hola, Player, ¿sabes qué es un “vórtice de fatalidad abisal”? Porque eso es lo que Oldak dice haber creado en su laboratorio. Se está haciendo cada vez más grande. Creo que va a explotar.",
        ["Run away!"] = "¡Huye!",
        ["Okay! Oldak! Grubfoot! Let’s get out of here! Grubfoot! Grubfoot’s stuck under a thing. I’m going back for him. Oh no! I’ve ended up somewhere else. The walls are red… I think this is the abyss. I can see a portal out, but there are some monsters in between it and me."] = "¡Está bien! ¡Oldak! ¡Grubfoot! ¡Salgamos de aquí! ¡Grubfoot! Grubfoot está atrapado debajo de algo. Voy a volver por él. ¡Oh, no! Terminé en otro lugar. Las paredes son rojas… Creo que esto es el abismo. Puedo ver un portal, pero hay algunos monstruos entre él y yo.",
        ["You should fight them."] = "Deberías luchar contra ellos.",
        ["Okay. I haven’t got my crossbow, but I’ve got a dagger. Here goes… There! They weren’t as tough as they looked. I’ve reached the portal. I’m home! And Grubfoot is fine. That’s a relief. Okay, I’m going to help Oldak clean up the mess. I’ll see you around, Player."] = "Está bien. No tengo mi ballesta, pero tengo una dagger. Aquí va… ¡Allí! No eran tan duros como parecían. He llegado al portal. ¡Estoy en casa! Y Grubfoot está bien. Eso es un alivio. Bien, voy a ayudar a Oldak a limpiar el desorden. Nos vemos por ahí, Player.",
        ["You should sneak past them."] = "Deberías pasarlos sigilosamente.",
        ["Okay, here goes… Carefully… Carefully… I’m past them, but there’s still some way to go… Oh no! They’ve seen me! I’ve got to run! I’m through! Phew! The portal is closed, and Grubfoot is fine. I’m going to help Oldak clean up the mess. I’ll see you around, Player."] = "Vale, aquí va... Con cuidado... Con cuidado... Ya los he superado, pero aún queda camino por recorrer... ¡Oh, no! ¡Me han visto! ¡Tengo que correr! ¡Ya terminé! ¡Uf! El portal está cerrado y Grubfoot está bien. Voy a ayudar a Oldak a limpiar el desorden. Nos vemos por ahí, Player.",
        ["You need to shut it down!"] = "¡Necesitas apagarlo!",
        ["Yeah, that’s what I was thinking. Hey, Oldak, Player thinks you should shut it down! Oh no! Oldak! Oldak’s paralysed! I can’t remember how to shut it down! What did Oldak say? It was either de-align the rune injector, or reverse the polarity on the polarity reverser."] = "Sí, eso es lo que estaba pensando. ¡Oye, Oldak, Player cree que deberías cerrarlo! ¡Oh, no! ¡Oldak! ¡Oldak está paralizado! ¡No recuerdo cómo apagarlo! ¿Qué dijo Oldak? Se trataba de desalinear el inyector de runas o invertir la polaridad en el inversor de polaridad.",
        ["De-align the injector!"] = "¡Desalinee el inyector!",
        ["Okay! Here goes… It worked! It’s shut off! But it’s left this red gunk all over the floor. Oldak is scraping some of it into a sample jar. A very interesting result, he says. Anyway, that looks like the end of that abyssal doom vortex. I’ll see you around, Player."] = "¡Está bien! Aquí va… ¡Funcionó! ¡Está apagado! Pero ha dejado esta porquería roja por todo el suelo. Oldak está raspando un poco en un frasco de muestra. Un resultado muy interesante, afirma. De todos modos, eso parece el final de ese vórtice abismal de fatalidad. Nos vemos por ahí, Player.",
        ["Reverse the polarity!"] = "¡Invierte la polaridad!",
        ["Okay, I’m turning this part the other way round… Wow… That’s the most amazing… it’s… indescribable."] = "Está bien, voy a darle la vuelta a esta parte... Vaya... Eso es lo más asombroso... es... indescriptible.",
        ["What was it? What happened?"] = "¿Qué fue? ¿Qué pasó?",
        ["I can’t describe it! It’s literally indescribable! Anyway, it’s gone now. I think I should leave Oldak and Grubfoot to work. I’ll see you around, Player."] = "¡No puedo describirlo! ¡Es literalmente indescriptible! De todos modos, ya no está. Creo que debería dejar que Oldak y Grubfoot funcionen. Nos vemos por ahí, Player.",
        ["Wotcha guv'na!"] = "¡Guau, guv'na!",
        ["Hello Zanik."] = "Hola Zanik.",
        ["What? You'd be surprised how many people expect me to say that. Anyway, how can I help?"] = "¿Qué? Te sorprendería saber cuánta gente espera que diga eso. De todos modos, ¿cómo puedo ayudar?",
        ["Can you tell me more about Soul Wars?"] = "¿Puedes contarme más sobre Soul Wars?",
        ["Such as?"] = "¿Por ejemplo?",
        ["Can I have another tutorial?"] = "¿Puedo tener otro tutorial?",
        ["Don't you know how to play already?"] = "¿Aún no sabes jugar?",
        ["I forgot."] = "Lo olvidé.",
        ["Well I have a guidebook if you want. I found crates of them if you need a copy."] = "Bueno, tengo una guía si quieres. Encontré cajas de ellos si necesitas una copia.",
        ["I want another tutorial."] = "Quiero otro tutorial.",
        ["Well, according to the notes Zimberfizz left you should be able to reply the tutorial in your mind."] = "Bueno, según las notas que dejó Zimberfizz deberías poder responder el tutorial en tu mente.",
        ["But how do I do that if I can't remember it?"] = "¿Pero cómo hago eso si no lo recuerdo?",
        ["Um, the notes say you have to think really hard about it. Give that a try?"] = "Um, las notas dicen que tienes que pensar mucho en ello. ¿Intentarlo?",
        ["Erm, okay. Hmmmmmm."] = "Erm, está bien. Mmmmmmm.",
        ["No, I don't think that's hard enough. Try again."] = "No, no creo que sea lo suficientemente difícil. Intentar otra vez.",
        ["Okay, okay. Huuuuuuuuuuuunnnnnnnghhh!"] = "Está bien, está bien. ¡Huuuuuuuuuuuunnnnnnnnghhh!",
        ["Wait, I can sense seomthing happening! Keep going!"] = "Espera, ¡puedo sentir que algo está sucediendo! ¡Sigue adelante!",
        ["Huuuuuuuuuuuuuuuuuuuuuuuuunnnnghhh!"] = "¡Huuuuuuuuuuuuuuuuuuuuuuuunnnnghhh!",
        ["*(Soul Wars tutorial begins)*"] = "*(Comienza el tutorial de Soul Wars)*",
        ["The book sounds good; could I have a copy?"] = "El libro suena bien; ¿podría tener una copia?",
        ["Here you are!"] = "¡Aquí tienes!",
        ["How are you feeling?"] = "¿Cómo te sientes?",
        ["It's complicated."] = "Es complicado.",
        ["On the one hand I'm 'alive' again, and out of that terrible nightmare."] = "Por un lado estoy 'vivo' otra vez, y fuera de esa terrible pesadilla.",
        ["On the other, Death has made it clear that I have to remain here. So I can't see any of my family or friends."] = "Por otro lado, la Muerte ha dejado claro que tengo que quedarme aquí. Entonces no puedo ver a ninguno de mis familiares o amigos.",
        ["Well, you come here, obviously, but not often enough."] = "Bueno, vienes aquí, obviamente, pero no con la suficiente frecuencia.",
        ["It also means my adventures are over. This is it for me now; the replacement for an imp in a silly hat."] = "También significa que mis aventuras han terminado. Esto es todo para mí ahora; el reemplazo de un diablillo con un sombrero tonto.",
        ["No family, no chance to redeem the Bandosians, no legacy with my own people."] = "Sin familia, sin posibilidad de redimir a los bandosianos, sin legado con mi propia gente.",
        ["Just me, Zanik, handing out capes."] = "Solo yo, Zanik, repartiendo capas.",
        ["But I really can't complain, can I? I have a friend who fought for me to drag me out of hell after all."] = "Pero realmente no me puedo quejar, ¿verdad? Después de todo, tengo un amigo que luchó por mí para sacarme del infierno.",
        ["How many people get a second chance like this? Well third chance. Fourth, if you count the possession thing."] = "¿Cuántas personas tienen una segunda oportunidad como ésta? Bueno, tercera oportunidad. Cuarto, si contamos lo de posesión.",
        ["So yeah... taking it day by day I guess."] = "Así que sí... supongo que tomándolo día a día.",
        ["Can we talk about rewards?"] = "¿Podemos hablar de recompensas?",
        ["Sure! There is a whole warehouse back here of things you can buy with Zeal."] = "¡Claro! Aquí detrás hay un almacén completo de cosas que puedes comprar con Zeal.",
        ["What kinds of rewards are there?"] = "¿Qué tipos de recompensas existen?",
        ["There are some discarded items related to Nomad."] = "Hay algunos elementos descartados relacionados con Nomad.",
        ["There are also strange blocks of white powder labeled{{Sic}} 'XP'. I don't know what they do but they are in high demand."] = "También hay extraños bloques de polvo blanco con la etiqueta {{Sic}} 'XP'. No sé a qué se dedican, pero tienen mucha demanda.",
        ["Would you like to take a look?"] = "¿Te gustaría echar un vistazo?",
        ["Yes, let's take a look."] = "Sí, echemos un vistazo.",
        ["No thanks, not right now."] = "No, gracias, ahora no.",
        ["Can we talk about ammunition?"] = "¿Podemos hablar de municiones?",
        ["*If you have not yet shown Ava's device*"] = "*Si aún no has mostrado el dispositivo de Ava*",
        ["You mean fletching?"] = "¿Te refieres a emplumar?",
        ["No, not like that! You see, I have this device here that helps return my ammunition."] = "¡No, así no! Verás, tengo este dispositivo aquí que me ayuda a devolver mis municiones.",
        ["You show (Ava's device) to Zanik."] = "Le muestras (el dispositivo de Ava) a Zanik.",
        ["How strange..."] = "Que extraño...",
        ["I was wondering; could you maybe make the team capes do something similar?"] = "Me preguntaba; ¿Podrías hacer que las capas del equipo hicieran algo similar?",
        ["Well I can't see how it'll hurt. Give me a minute. I think I saw a spell that can do the same around here somewhere..."] = "Bueno, no veo cómo dolerá. Dame un minuto. Creo que vi un hechizo que puede hacer lo mismo por aquí en alguna parte...",
        ["Zanik mutters an incantation and enchants your Soul Wars team capes."] = "Zanik murmura un encantamiento y encanta las capas de tu equipo de Soul Wars.",
        ["There! Obviously this doesn't use the same scientific principals as your device, but it should work."] = "¡Ahí! Obviamente, esto no utiliza los mismos principios científicos que su dispositivo, pero debería funcionar.",
        ["I have a feeling that they will only affect Soul Wars though. Sorry!"] = "Aunque tengo la sensación de que solo afectarán a Soul Wars. ¡Lo siento!",
        ["Thanks!"] = "¡Gracias!",
        ["*If you have already shown Ava's device*"] = "*Si ya has mostrado el dispositivo de Ava*",
        ["How are the new capes working for you?"] = "¿Cómo te funcionan las nuevas capas?",
        ["Just fine, thanks."] = "Muy bien, gracias.",
        ["Great!"] = "¡Genial!",
        ["Can we talk about my own Soul Wars cape?"] = "¿Podemos hablar de mi propia capa de Soul Wars?",
        ["Can we talk about my Soul Wars cape?"] = "¿Podemos hablar de mi capa de Soul Wars?",
        ["Of course. What's the matter?"] = "Por supuesto. ¿Qué pasa?",
        ["Could I swap my cape for a different colour?"] = "¿Puedo cambiar mi capa por un color diferente?",
        ["Really? Changing your wardrobe for the season, Player?"] = "¿En serio? Cambiando de armario para la temporada, ¿Player?",
        ["What can I say? I am a creature of fashion!"] = "¿Qué puedo decir? ¡Soy una criatura de la moda!",
        ["Can we talk about you?"] = "¿Podemos hablar de ti?",
        ["I'd like to talk about your new adventures."] = "Me gustaría hablar sobre tus nuevas aventuras.",
        ["Zanik's latest adventure"] = "La última aventura de Zanik",
        ["I'm taking a break from adventuring for a bit. I want to focus on the obelisk."] = "Me tomaré un descanso de las aventuras por un tiempo. Quiero centrarme en el obelisco.",
        ["Why? Is it doing something strange?"] = "¿Por qué? ¿Está haciendo algo extraño?",
        ["No... but it might. It's been over a year since we defeated Nomad and... well... I want to make sure he stays defeated."] = "No... pero podría serlo. Ha pasado más de un año desde que derrotamos a Nomad y... bueno... quiero asegurarme de que siga derrotado.",
        ["One of Zanik's earlier adventures"] = "Una de las primeras aventuras de Zanik.",
        ["Dungeon Diving"] = "Buceo en mazmorras",
        ["So Meg and I deciding that we'd see about heading into Daemonheim together."] = "Así que Meg y yo decidimos que estudiaríamos la posibilidad de entrar juntos en Daemonheim.",
        ["We figured that we'd have a better time working together."] = "Pensamos que lo pasaríamos mejor trabajando juntos.",
        ["How did it go?"] = "¿Cómo te fue?",
        ["Between you and me, Meg is awful to go Dungeoneering with. She spends all of her time trying to improve her firemaking..."] = "Entre tú y yo, es horrible combinar Meg con Dungeoneering. Ella pasa todo su tiempo tratando de mejorar su forma de hacer fuego...",
        ["Or growing potatoes. Everywhere! So many potatoes. How does anyone even eat that many potatoes?"] = "O cultivar patatas. ¡En todos lados! Tantas patatas. ¿Cómo es posible que alguien coma tantas patatas?",
        ["Feline Fine"] = "felino fino",
        ["The world is very, very, very weird. I found an amulet that looked like a cat's face... do you know what it did?"] = "El mundo es muy, muy, muy extraño. Encontré un amuleto que parecía la cara de un gato... ¿sabes qué hacía?",
        ["Let you talk to cats? It sounds like the amulet of catspeak."] = "¿Te dejas hablar con los gatos? Suena como el amuleto de la lengua gatuna.",
        ["Well... yes. But it's weird! Do you know what cats are saying all the time?"] = "Bueno... sí. ¡Pero es raro! ¿Sabes lo que dicen los gatos todo el tiempo?",
        ["Insane, insane things! They think they're the rulers of the world, that the kings and queens are their pets."] = "¡Cosas locas, locas! Creen que son los gobernantes del mundo, que los reyes y las reinas son sus mascotas.",
        ["It's like there's a weird conspiracy where cats are controlling us..."] = "Es como si hubiera una extraña conspiración en la que los gatos nos controlan...",
        ["I think you're getting paranoid now."] = "Creo que ahora te estás volviendo paranoico.",
        ["You're probably right. I'm sure there are no cats planning to take over the world."] = "Probablemente tengas razón. Estoy seguro de que no hay gatos que planeen dominar el mundo.",
        ["I felt I should go and pay my respect to Astrid's family. She...didn't deserve what happened."] = "Sentí que debía ir y presentar mis respetos a la familia de Astrid. Ella... no merecía lo que pasó.",
        ["But the Fremennik wouldn't talk to me. They just turned their nose up at me and called me 'Outsider."] = "Pero el Fremennik no quiso hablarme. Simplemente me miraron con desprecio y me llamaron 'forastero'.",
        ["Which I felt was quite rude."] = "Lo cual me pareció bastante grosero.",
        ["But then one of them slipped up, they mentioned that you can be considered Fremenniks if you can complete certain trials and win the respect of the council"] = "Pero entonces uno de ellos cometió un desliz, mencionó que pueden ser considerados Fremenniks si pueden completar ciertas pruebas y ganarse el respeto del consejo.",
        ["So that's what I set out to do."] = "Eso es lo que me propuse hacer.",
        ["it wasn't easy to get them to talk to me, to even hint at the trials, but I won them over."] = "No fue fácil lograr que hablaran conmigo, que siquiera insinuaran las pruebas, pero los gané.",
        ["The first person wanted me to drink a vast quantity of beer. I really don't think he took into account the stomach of a cave goblin."] = "La primera persona quería que bebiera una gran cantidad de cerveza. Realmente no creo que haya tenido en cuenta el estómago de un duende de las cavernas.",
        ["He murmured his vote from under the table."] = "Murmuró su voto desde debajo de la mesa.",
        ["The trial of perception was surprisingly easy, big eyes helps I guess."] = "La prueba de percepción fue sorprendentemente fácil, supongo que los ojos grandes ayudan.",
        ["The only trial that was particularly difficult was the trial of the warrior."] = "La única prueba que fue particularmente difícil fue la prueba del guerrero.",
        ["A mahjarrat! I had to punch a mahjarrat. Punching their faces hurt and I am not the best pugilist in the world."] = "¡Un mahjarrat! Tuve que darle un puñetazo a un mahjarrat. Golpearles la cara duele y no soy el mejor pugilista del mundo.",
        ["It took a while, but I had completed seven trials and had secured seven votes."] = "Me tomó un tiempo, pero completé siete pruebas y obtuve siete votos.",
        ["Which means that the council can consider me an honourary member of their clan. As soon as they submit their votes."] = "Lo que significa que el consejo puede considerarme miembro honorario de su clan. Tan pronto como presenten sus votos.",
        ["I expect the confirmation letter any day now."] = "Espero la carta de confirmación en cualquier momento.",
        ["They do seem to take a long time submitting their votes."] = "Parece que tardan mucho en enviar sus votos.",
        ["Who are you going to summon"] = "¿A quién vas a convocar?",
        ["There are some skills that I ca't just get to grips with. Summoning is one of them."] = "Hay algunas habilidades que no puedo dominar. Summoning es uno de ellos.",
        ["I found the druids at Taverley and asked them to train me in the ways of Summoning."] = "Encontré a los druidas en Taverley y les pedí que me entrenaran en los métodos de Summoning.",
        ["It apears as though my ability to reach out to the spiritual plane is...damaged."] = "Parece que mi capacidad para alcanzar el plano espiritual está... dañada.",
        ["Could it be linked to...you know...dying?"] = "¿Podría estar relacionado con... ya sabes... morir?",
        ["Maybe. I couldn't say, suffice to say I am no summoner."] = "Quizás. No podría decirlo, basta con decir que no soy un invocador.",
        ["The Demon's Pact"] = "El pacto del demonio",
        ["Not al of my adventurers have been fun game, this one was...difficult."] = "No todos mis aventureros han sido juegos divertidos, este fue... difícil.",
        ["I was wandering near Draynor when I found a run down shack and sobs coming from inside it."] = "Estaba deambulando cerca de Draynor cuando encontré una choza deteriorada y sollozos saliendo de su interior.",
        ["I went to investigate and found a house overturned and a woman weeping into a bundle of cloths."] = "Fui a investigar y encontré una casa volcada y una mujer llorando sobre un fardo de ropa.",
        ["It took me a few moments to realise that it wasn't just crumpled laundry."] = "Me tomó unos momentos darme cuenta de que no era solo ropa arrugada.",
        ["The woman begged me, pleaded, for a way to save...to undo this tragedy...but I had no solution."] = "La mujer me suplicó, suplicó, una forma de salvar... de deshacer esta tragedia... pero no tuve solución.",
        ["That's when he arrived."] = "Fue entonces cuando llegó.",
        ["I didn't see his face, he was hidden behind a cowl, deliberately mysterious."] = "No vi su rostro, estaba escondido detrás de una capucha, deliberadamente misterioso.",
        ["He gave the woman a choice, he could undo what had happened, but only by shortening her own lifespan."] = "Le dio a la mujer una opción, podía deshacer lo que había sucedido, pero solo acortando su propia vida.",
        ["The child would live, but she would die before her time. A cruel bargain."] = "La niña viviría, pero moriría antes de tiempo. Un trato cruel.",
        ["He was...regretful of the terms...but he claimed there was no alternative."] = "Estaba... arrepentido de los términos... pero afirmó que no había alternativa.",
        ["She accepted...but I left before I could see them seal the deal."] = "Ella aceptó... pero me fui antes de que pudiera verlos cerrar el trato.",
        ["as I left, just before the house disappeared from view, I swear I heard a baby crying."] = "cuando salí, justo antes de que la casa desapareciera de mi vista, juro que escuché a un bebé llorar.",
        ["Zanik Owned Ports"] = "Puertos propiedad de Zanik",
        ["I was spending time with Meg, Exploring, as you do, when she mentioned ports to the Eastern lands."] = "Estaba pasando tiempo con Meg, explorando, como lo haces tú, cuando mencionó los puertos a las tierras del este.",
        ["I thought to myself 'I want in on that' and so I set off to see what I could do."] = "Pensé: \"Quiero participar en eso\", así que me puse en marcha para ver qué podía hacer.",
        ["Sadly I was unable to get enough funds together to set up anything remotely similar to a port."] = "Lamentablemente no pude reunir suficientes fondos para configurar algo remotamente similar a un puerto.",
        ["But I was able to get a nice little rowboat and I hired some out of work zombie pirates to sail it for me."] = "Pero pude conseguir un pequeño bote de remos y contraté a unos piratas zombis desempleados para que lo navegaran por mí.",
        ["Good working guys those; smelly, but good working."] = "Buenos trabajadores, esos; Huele mal, pero funciona bien.",
        ["The sous-chef's assistant"] = "El ayudante del segundo chef.",
        ["Continuing on from our adventures, Meg and I decided that we'd explore Lumbridge a bit more."] = "Continuando con nuestras aventuras, Meg y yo decidimos explorar Lumbridge un poco más.",
        ["There we were accosted by a panicked kitchen assistant who was desperately short on the ingredient needed for the Duke's morning crumpet."] = "Allí nos abordó un asistente de cocina en pánico que estaba desesperadamente escaso de los ingredientes necesarios para el bollo matutino del Duque.",
        ["Ever ready to help someone in need, Meg and I set out to find the missing ingredients."] = "Siempre listos para ayudar a alguien que lo necesita, Meg y yo nos propusimos encontrar los ingredientes que faltaban.",
        ["All in all it took about 12 seconds as there was a farm nearby with the flour, and the butter and milk were easy enough to get."] = "En total, tomó unos 12 segundos, ya que había una granja cercana con la harina y la mantequilla y la leche eran bastante fáciles de conseguir.",
        ["Frankly I think this kitchen assistant was just to lazy to get them himself. A bit of a let down really."] = "Francamente, creo que este ayudante de cocina era demasiado vago para conseguirlos él mismo. Realmente un poco decepcionante.",
        ["So Meg and I grabbed a couple more bits and bobs and had a nice picnic down on the bank of the Salve."] = "Así que Meg y yo tomamos un par de cosas más y hicimos un agradable picnic en la orilla del Salve.",
        ["There we encountered a strange pig that gave us electric shock when we tried to pet it. Weird."] = "Allí nos encontramos con un cerdo extraño que nos dio una descarga eléctrica cuando intentamos acariciarlo. Extraño.",
        ["X marks the spot"] = "X marca el lugar",
        ["I met a young adventurer called Meg and we got talking about our adventures. She seemed rather fond of you, I must say."] = "Conocí a un joven aventurero llamado Meg y empezamos a hablar de nuestras aventuras. Parecía bastante encariñada contigo, debo decir.",
        ["She showed me a treasure map that she had procured from a strange peg-legged man."] = "Me mostró un mapa del tesoro que le había conseguido a un extraño hombre con patas de palo.",
        ["Together we followed the map across turbulent oceans, past pirates armed to the teeth and even into the lair of a strange metallic red dragon."] = "Juntos seguimos el mapa a través de océanos turbulentos, pasando por piratas armados hasta los dientes e incluso hasta la guarida de un extraño dragón rojo metálico.",
        ["When we finally reached the spot it turned out that there was another treasure map leading us all the way back to where we started."] = "Cuando finalmente llegamos al lugar, resultó que había otro mapa del tesoro que nos llevaba de regreso al punto de partida.",
        ["I think it was some sort of scam, but we had fun along the way."] = "Creo que fue una especie de estafa, pero nos divertimos en el camino.",
        ["Visiting old friends"] = "Visitando a viejos amigos",
        ["I met up with Ariane and Sir Owen, I've not spoken to them in quite some time."] = "Me reuní con Ariane y Sir Owen, no he hablado con ellos desde hace bastante tiempo.",
        ["Owen seemed reluctant to talk to me. I think he is concerned with my sudden resurrection."] = "Owen parecía reacio a hablar conmigo. Creo que está preocupado por mi repentina resurrección.",
        ["Ariane seemed more interested in discussing the afterlife than our adventures, but it was nice to catch up."] = "Ariane parecía más interesado en hablar del más allá que de nuestras aventuras, pero fue agradable ponerse al día.",
        ["Then I went to visit Xenia's grave."] = "Luego fui a visitar la tumba de Xenia.",
        ["She had always been so...distant before. But speaking to her in the Underworld..."] = "Ella siempre había sido tan... distante antes. Pero hablar con ella en el Inframundo...",
        ["She hid her grief quite well I think, but I saw how much it ate away at her."] = "Creo que ocultó bastante bien su dolor, pero vi cuánto la devoraba.",
        ["She was led astray and made a mistake, a big one, yes, but a mistake. It cost her everything and yet still she punishes herself."] = "Ella se desvió y cometió un error, uno grande, sí, pero un error. Le costó todo y aun así se castiga a sí misma.",
        ["I think I'd have liked to get to know her better."] = "Creo que me hubiera gustado conocerla mejor.",
        ["One tiny favour"] = "un pequeño favor",
        ["I went to explore Karamja and there I met a man called Yanni."] = "Fui a explorar Karamja y allí conocí a un hombre llamado Yanni.",
        ["He asked me if I could run a quick errand for him..."] = "Me preguntó si podía hacerle un recado rápido...",
        ["That was a month ago... I've only just gotten back."] = "Eso fue hace un mes... Acabo de regresar.",
        ["Saying hi to highwaymen"] = "Saludando a los bandoleros",
        ["After returning to life I felt reinvigorated. Like I was finally myself."] = "Después de regresar a la vida me sentí revitalizado. Como si finalmente fuera yo mismo.",
        ["I took this as an opportunity to go on a nice long walk."] = "Aproveché esta oportunidad para dar un largo y agradable paseo.",
        ["Along the way I encountered a strange man with a mask covering his face and a wide brimmed hat."] = "En el camino me encontré con un hombre extraño con una máscara que le cubría el rostro y un sombrero de ala ancha.",
        ["He told me 'Your money or your life', which seemed terribly unfair of him, but I had no money."] = "Me dijo 'Tu dinero o tu vida', lo cual le pareció terriblemente injusto, pero yo no tenía dinero.",
        ["So I opted for a compromise and shot him in the foot with my crossbow."] = "Así que opté por un compromiso y le disparé en el pie con mi ballesta.",
        ["I told him the bolt's probably worth some money and, as he hopped on the spot, he seemed to agree."] = "Le dije que el rayo probablemente valía algo de dinero y, mientras saltaba en el lugar, pareció estar de acuerdo.",
        ["So that was fun."] = "Así que fue divertido.",
        ["What can you tell me about the soul obelisk?"] = "¿Qué me puedes decir sobre el obelisco del alma?",
        ["It seems to be stable at least. I'm not sure what it is exactly, or how it works, but it's not doing anything dangerous."] = "Al menos parece estable. No estoy seguro de qué es exactamente ni cómo funciona, pero no hace nada peligroso.",
        ["Can you take me to the throne?"] = "¿Puedes llevarme al trono?",
        ["*Zanik takes you to Nomad's throne room*"] = "*Zanik te lleva a la sala del trono de Nomad*",
        ["There's not a lot going on here at the moment, but you can have a look around if you want."] = "No están sucediendo muchas cosas aquí en este momento, pero puedes echar un vistazo si quieres.",
        ["*If you are already in Nomad's throne room*"] = "*Si ya estás en la sala del trono de Nomad*",
        ["...ta-da!"] = "... ¡ta-da!",
        ["Good work, Zanik. Keep it up."] = "Buen trabajo, Zanik. Avanza.",
        ["Let's talk about something else."] = "Hablemos de otra cosa.",
        ["What can you tell me about the afterlife?"] = "¿Qué puedes decirme sobre el más allá?",
        ["Do... do we have to talk about that? It's not a memory I want to recall."] = "¿Tenemos... tenemos que hablar de eso? No es un recuerdo que quiera recordar.",
        ["I want to know."] = "Quiero saber.",
        ["Very well. It was... horrible. Imagine seeing all of the friends and family that you thought lost?"] = "Muy bien. Fue... horrible. ¿Imaginas ver a todos los amigos y familiares que creías perdidos?",
        ["People you grew up with that had died and moved on."] = "Personas con las que creciste que murieron y siguieron adelante.",
        ["That brief burst of jubilation as you see them again. Your heart, though cold, beats faster just for a moment."] = "Ese breve estallido de júbilo cuando los vuelves a ver. Tu corazón, aunque frío, late más rápido sólo por un momento.",
        ["For a moment you think you must be somewhere good. Somewhere happy."] = "Por un momento piensas que debes estar en algún buen lugar. En algún lugar feliz.",
        ["Which makes it all the more painful when you see them torn from you and slaughtered mercilessly by the forces you had hoped to escape."] = "Lo que lo hace aún más doloroso cuando los ves arrebatados y masacrados sin piedad por las fuerzas de las que esperabas escapar.",
        ["I saw them die over and over and over again. Each death as horrible to witness as the last. Never ending."] = "Los vi morir una y otra y otra vez. Cada muerte es tan horrible de presenciar como la anterior. Sin fin.",
        ["Time flows differently there, before you arrived I had seen them die thousands of times and each time I had been unable to stop it."] = "Allí el tiempo fluye diferente, antes de que llegaras los había visto morir miles de veces y cada vez no había podido detenerlo.",
        ["I was helpless, hopeless, and alone, and everyone I loved was suffering because of me."] = "Estaba indefenso, desesperado y solo, y todos los que amaba sufrían por mi culpa.",
        ["That guilt was almost as painful as the swords and axes that cut me to ribbons each day."] = "Esa culpa era casi tan dolorosa como las espadas y hachas que me cortaban en pedazos cada día.",
        ["Let me tell you, those Bandosians delighted in pain. They found new ways to kill me, each more painful than the last."] = "Déjame decirte que esos bandosianos se deleitaban con el dolor. Encontraron nuevas formas de matarme, cada una más dolorosa que la anterior.",
        ["I...please, that's enough. I don't want to relive it anymore."] = "Yo... por favor, ya es suficiente. No quiero revivirlo más.",
        ["I'm sorry Zanik."] = "Lo siento Zanik.",
        ["It's ok Player, you saved me from there. I will always love you for that."] = "Está bien Player, me salvaste de allí. Siempre te amaré por eso.",
        ["Love?"] = "¿Amor?",
        ["Erm... I will always thank you for that...don't...er... Don't read anything into that ok?"] = "Erm... Siempre te agradeceré por eso... no... er... No leas nada en eso, ¿vale?",
        ["[Flirt]"] = "[coquetear]",
        ["But what if I want to read something into that?"] = "¿Pero qué pasa si quiero leer algo sobre eso?",
        ["Then please excuse me whilst I turn bright red and gibber in an incoherently embarassing manner."] = "Entonces, por favor, discúlpenme mientras me pongo rojo brillante y farfullo de una manera incoherente y vergonzosa.",
        ["Duly noted."] = "Debidamente anotado.",
        ["[Move on]"] = "[seguir adelante]",
        ["Any time."] = "En cualquier momento.",
        ["You deserved it."] = "Te lo merecías.",
        ["You're right, I'm sorry."] = "Tienes razón, lo siento.",
        ["Thank you, Player."] = "Gracias, Player.",
        ["What happened on Yu'Biusk?"] = "¿Qué pasó en Yu'Biusk?",
        ["It was good at first. We set up a new camp and began the beginnings of a new home."] = "Al principio estuvo bien. Instalamos un nuevo campamento y comenzamos los inicios de un nuevo hogar.",
        ["I taught the Bandosians how to direct their battle lust differently, using their strength to move stones and destroy dangers."] = "Les enseñé a los bandosianos cómo dirigir su ansia de batalla de manera diferente, usando su fuerza para mover piedras y destruir peligros.",
        ["We set up a tournament, bloodless of course, for the warriors to prove themselves in accordance with their beliefs."] = "Organizamos un torneo, incruento por supuesto, para que los guerreros demuestren su valía de acuerdo con sus creencias.",
        ["It was starting to become something good. I was genuinely happy and I felt a surge of vigour that made me think my affliction had gone."] = "Estaba empezando a convertirse en algo bueno. Estaba genuinamente feliz y sentí una oleada de vigor que me hizo pensar que mi aflicción había desaparecido.",
        ["But then I had the dreams. In the dreams I was being torn apart by tiny clawed hands that seemed to grow from my stomach. Ripping me apart from the inside out."] = "Pero luego tuve sueños. En los sueños me destrozaban unas pequeñas manos con garras que parecían crecer desde mi estómago. Desgarrándome desde adentro hacia afuera.",
        ["Each morning I awoke feeling more and more drained and less and less... whole."] = "Cada mañana me despertaba sintiéndome cada vez más agotado y cada vez menos... completo.",
        ["Then one night I just... drifted away... and then I awoke in that nightmare you saved me from."] = "Entonces una noche simplemente... me alejé... y luego desperté en esa pesadilla de la que me salvaste.",
        ["Goodbye Player."] = "Adiós Player.",
        ["Bye, Zanik."] = "Adiós, Zanik.",
        ["See you later."] = "Hasta luego.",
        ["**REMOVE THE ENCHANTMENT?**"] = "**¿QUITAR EL ENCANTO?**",
        ["Yes"] = "si",
        ["There you go."] = "Ahí lo tienes.",
        ["Hello, Player! Welcome to the Warforge Dig Site!"] = "¡Hola, Player! ¡Bienvenido al sitio de excavación de Warforge!",
        ["You need to complete the Archaeology tutorial before you can work at this site."] = "Debe completar el tutorial de Archaeology antes de poder trabajar en este sitio.",
        ["Speak to Acting Guildmaster Reiniger at the Archaeology campus, east of the Varrock lodestone, to learn more."] = "Hable con Acting Guildmaster Reiniger en el campus de Archaeology, al este de Varrock lodestone, para obtener más información.",
        ["You need 76 Archaeology to access this site."] = "Necesita 76 Archaeology para acceder a este sitio.",
        ["The monolith shared what it could about the Warforge, but it's as you would expect from a Bandosian construction."] = "El monolito compartió lo que pudo sobre Warforge, pero es lo que se esperaría de una construcción bandosiana.",
        ["Bandos's mercenary armies are quite well documented in comparison to other Third Age events, after all, and they had to be trained somewhere."] = "Después de todo, los ejércitos mercenarios de Bandos están bastante bien documentados en comparación con otros eventos de la Tercera Edad, y tuvieron que ser entrenados en alguna parte.",
        ["What strikes me most, however, is that the few artefacts discovered so far are not consistent with other Bandosian creations."] = "Lo que más me sorprende, sin embargo, es que los pocos artefactos descubiertos hasta ahora no coinciden con otras creaciones bandosianas.",
        ["Who or what created the armaments for Bandos's mercenaries, and why is this secret so well buried?"] = "¿Quién o qué creó el armamento para los mercenarios de Bandos y por qué este secreto está tan bien enterrado?",
        ["Bandos's capriciousness and cruelty knew no bounds. Prior to his eviction, he buried his goblin charges beneath the dirt."] = "El capricho y la crueldad de Bandos no conocían límites. Antes de su desalojo, enterró a sus duendes bajo la tierra.",
        ["Left them to splinter and fight, trapped in darkness - the forge wars - and to devolve into beings bent only on fighting for survival."] = "Los dejó para que se fragmentaran y lucharan, atrapados en la oscuridad (las guerras forjadas) y para que se convirtieran en seres empeñados únicamente en luchar por la supervivencia.",
        ["The abducted imcando dwarf, Thalmund, once the flaming heart of the Warforge, was their only saviour."] = "El enano imcando secuestrado, Thalmund, que alguna vez fue el corazón en llamas de Warforge, fue su único salvador.",
        ["All goblins revered him for his fine weaponsmithing, and so was he able to eventually dig an escape tunnel and lead them back to the surface."] = "Todos los duendes lo veneraban por su excelente fabricación de armas, por lo que finalmente pudo cavar un túnel de escape y llevarlos de regreso a la superficie.",
        ["You need [number] free inventory [space/spaces]."] = "Necesitas [número] inventario gratuito [space/spaces].",
        ["I'm holding on to some cave paintings you found."] = "Tengo algunas pinturas rupestres que encontraste.",
        ["I found this cave painting thing - did you lose this?"] = "Encontré esta pintura rupestre. ¿La perdiste?",
        ["Take cave painting relic components back?"] = "¿Recuperar los componentes de las reliquias de pinturas rupestres?",
        ["Yes."] = "Sí.",
        ["Okay, just let me know when you want it back."] = "Está bien, avísame cuando quieras recuperarlo.",
        ["Select an option"] = "Seleccione una opción",
        ["Why are you the site manager here?"] = "¿Por qué eres el administrador del sitio aquí?",
        ["I know, it is confusing for me too. You die, a god resurrects you, you die again, get tormented in a Bandosian hellscape, get rescued from it by a friend - thank you for that again, by the way - become an emissary of the Underworld and then end up as a consultant for the Archaeology Guild."] = "Lo sé, a mí también me resulta confuso. Mueres, un dios te resucita, mueres de nuevo, te atormentan en un infierno bandosiano, un amigo te rescata de él (gracias por eso de nuevo, por cierto), te conviertes en un emisario del inframundo y luego terminas como consultor del gremio Archaeology.",
        ["I would not believe it myself if I had not lived it. And, er, died it?"] = "Ni yo mismo lo creería si no lo hubiera vivido. Y, eh, ¿murió?",
        ["That's a lot, but hey, you're here now. Why you and why here?"] = "Eso es mucho, pero bueno, ya estás aquí. ¿Por qué tú y por qué aquí?",
        ["I am unsure... Icthlarin, shall we say, 'strongly advised' me to offer my expertise. Apparently, this site was once home to goblins, including the Dorgeshuun before they renounced Bandos."] = "No estoy seguro... Icthlarin, digamos, \"me recomendó encarecidamente\" que ofreciera mi experiencia. Aparentemente, este sitio alguna vez fue el hogar de duendes, incluido el Dorgeshuun antes de que renunciaran a Bandos.",
        ["It is possible I have ancestors buried here. I think Icthlarin sent me here to learn something in particular, though he did not hint at what."] = "Es posible que tenga antepasados enterrados aquí. Creo que Icthlarin me envió aquí para aprender algo en particular, aunque no insinuó qué.",
        ["Well, I'd be happy to help in whatever way I can."] = "Bueno, estaré encantado de ayudarte en todo lo que pueda.",
        ["Thank you, Player. You are a true friend."] = "Gracias, Player. Eres un verdadero amigo.",
        ["What is this dig site about?"] = "¿De qué se trata este sitio de excavación?",
        ["The Warforge... If initial reports are to be believed, this is where Bandos moulded goblins into warriors."] = "The Warforge... Si hay que creer en los informes iniciales, aquí es donde Bandos transformó a los duendes en guerreros.",
        ["Goblins were sent here at a young age to learn how to fight, how to survive, and then be sold off to fight for people they didn't know and in wars they didn't care about."] = "Los duendes fueron enviados aquí a una edad temprana para aprender a luchar, a sobrevivir y luego ser vendidos para luchar por personas que no conocían y en guerras que no les importaban.",
        ["So it was something of a school of warfare, you could say, but knowing Bandos a cruel and hard place."] = "Así que se podría decir que era una especie de escuela de guerra, pero conocer a Bandos era un lugar cruel y duro.",
        ["Why call it the Warforge, though."] = "Pero ¿por qué llamarlo Warforge?",
        ["I guess it was figurative? Forging young goblins into battle-ready mercenaries?"] = "¿Supongo que fue figurativo? ¿Convertir a jóvenes duendes en mercenarios listos para la batalla?",
        ["I want to talk about mysteries."] = "Quiero hablar de misterios.",
        ["Bye."] = "Adiós.",
        ["Talk to you later, Player."] = "Nos vemos luego, Player.",
        ["Oh, I do not think you have found any yet, Player. I am sure you will stumble across something soon, though."] = "Oh, no creo que hayas encontrado ninguno todavía, Player. Sin embargo, estoy seguro de que pronto te toparás con algo.",
        ["Which mystery would you like to discuss?"] = "¿Qué misterio te gustaría discutir?",
        ["Out of the Crucible."] = "Fuera del Crisol.",
        ["Into the Forge."] = "En la fragua.",
        ["You Have Chosen..."] = "Tú has elegido...",
        ["[More options]"] = "[Más opciones]",
        ["The First Commander."] = "El Primer Comandante.",
        ["Forge War!"] = "¡Forja War!",
        ["Heart of the Forge."] = "Corazón de la Forja.",
        ["A familiar face has arrived in the pub."] = "Una cara familiar ha llegado al pub.",
        ["No what?"] = "¿No qué?",
        ["No to whatever it is you were thinking of asking me."] = "No a lo que sea que estuvieras pensando en preguntarme.",
        ["But..."] = "Pero...",
        ["Look, I'm dead, I'm tired, I'm burnt out, and I'm overused. I need a break."] = "Mira, estoy muerto, estoy cansado, estoy agotado y estoy abusado. Necesito un descanso.",
        ["Even becoming an  site manager might have been a stretch too far."] = "Incluso convertirse en administrador de un sitio podría haber sido ir demasiado lejos.",
        ["Can't help, won't help. Sorry."] = "No puedo ayudar, no ayudaré. Lo siento.",
        ["Wait, not even helping me to take out Rasial, the evil necromancer?"] = "Espera, ¿ni siquiera me ayudas a eliminar a Rasial, el malvado nigromante?",
        ["Not even."] = "Ni siquiera.",
        ["I'm just playing darts and having a drink."] = "Solo estoy jugando a los dardos y tomando una copa.",
        ["So, please...just let me rest in peace."] = "Entonces, por favor... déjame descansar en paz.",
        ["0 souls fly over to power the vessel. Zanik is serious about sitting this one out."] = "0 almas vuelan para impulsar la nave. Zanik se toma en serio la idea de no participar en esto.",
        ["In peace."] = "En paz.",
        ["Here, you seem like you could use a drink."] = "Aquí, parece que te vendría bien un trago.",
        ["What's the catch?"] = "¿Cuál es el problema?",
        ["There's no catch - you're my friend, and you're tired, so I decided to buy you a drink."] = "No hay truco: eres mi amigo y estás cansado, así que decidí invitarte a una bebida.",
        ["Congratulations! You have completed: 'Alms of Death to the Dorgeshuun' - Buy Zanik the Alms of Death."] = "¡Felicitaciones! Has completado: 'La limosna de la muerte al Dorgeshuun' - Compra Zanik la limosna de la muerte.",
        ["Alright... Thanks, Player."] = "Muy bien... Gracias, Player.",
    },
    ["Zarador"] = {
        ["Hey, grunt! Feel you're strong enough to honour the mighty Bandos?"] = "¡Oye, gruñido! ¿Sientes que eres lo suficientemente fuerte como para honrar al poderoso Bandos?",
        ["Speak to the recruiter. Demonstrate your strength over the feeble Armadyleans."] = "Habla con el reclutador. Demuestra tu fuerza sobre los débiles Armadyleans.",
        ["I knew you couldn't resist a good fight. Victory for Bandos!"] = "Sabía que no podrías resistirte a una buena pelea. ¡Victoria para Bandos!",
        ["You have been demonstrating your strength well so far. Is there anything you need to know?"] = "Hasta ahora has demostrado bien tu fuerza. ¿Hay algo que necesites saber?",
        ["I have questions..."] = "Tengo preguntas...",
        ["I don't have time for questions! Prove you're strong enough, then I might deign to answer."] = "¡No tengo tiempo para preguntas! Demuestra que eres lo suficientemente fuerte y entonces podría dignarme a responder.",
        ["What are my orders?"] = "¿Cuáles son mis pedidos?",
        ["Collect divine energy at our caravans. Fight Armadylean caravans, and destroy them. Claim land for us by building along the convoy routes. Our strength will rise."] = "Recoge energía divina en nuestras caravanas. Lucha contra las caravanas armadyleanas y destrúyelas. Reclama terrenos para nosotros construyendo a lo largo de las rutas de los convoyes. Nuestra fuerza aumentará.",
        ["Just reporting in."] = "Recién informo.",
        ["Show your strength to Bandos and glory will be ours."] = "Muestra tu fuerza a Bandos y la gloria será nuestra.",
        ["Your courage in battle has been recognised by Bandos. How can I help you?"] = "Bandos ha reconocido tu valentía en la batalla. ¿Le puedo ayudar en algo?",
        ["How's the battle going?"] = "¿Cómo va la batalla?",
        ["Our warriors out there are too weak. We're at a stalemate with the Armadylean forces. Show them the strength of Bandos by wreaking their convoys."] = "Nuestros guerreros son demasiado débiles. Estamos en un punto muerto con las fuerzas armadyleanas. Muéstrales la fuerza de Bandos destruyendo sus convoyes.",
        ["Can you tell me about the gods?"] = "¿Puedes hablarme de los dioses?",
        ["Bandos is the strongest of all warriors. When he wins battles, he doesn't win by margins, he wins by great distances. He is a master strategist. He can turn certain defeat into a rout. And the troops die, knowing they supported the great god Bandos. The devices I create are used by Bandos himself, and I am proud to serve him in the ultimate victory."] = "Bandos es el más fuerte de todos los guerreros. Cuando gana batallas, no gana por márgenes, gana por grandes distancias. Es un maestro estratega. Puede convertir una derrota segura en una derrota. Y las tropas mueren, sabiendo que apoyaban al gran dios Bandos. Los dispositivos que creo son utilizados por el propio Bandos y estoy orgulloso de poder servirle en la victoria final.",
        ["Armadyl's under the impression that the gods can live in peace. Sounds like madness to me. War thrives - that never changes. Armadyl has only failed in the past. He doesn't understand what it's like to win. Do you want someone on the throne who has never tasted success? Once Bandos defeats him, there'll be no place for his weakness in this world."] = "Armadyl tiene la impresión de que los dioses pueden vivir en paz. Me parece una locura. War prospera, eso nunca cambia. Armadyl sólo ha fracasado en el pasado. No entiende lo que es ganar. ¿Quieres que suba al trono alguien que nunca haya probado el éxito? Una vez que Bandos lo derrote, no habrá lugar para su debilidad en este mundo.",
        ["Guthix did all he could to dodge war. If he was so strong, so ancient, then why did he only delay the other gods? He must have known the storm he was brewing. People see him as great, but I see him as a coward. The weak always die eventually."] = "Guthix hizo todo lo que pudo para evitar la guerra. Si era tan fuerte, tan antiguo, ¿por qué sólo retrasó a los otros dioses? Debía haber sabido la tormenta que se estaba gestando. La gente lo ve genial, pero yo lo veo como un cobarde. Los débiles siempre mueren al final.",
        ["I have questions about you."] = "Tengo preguntas sobre ti.",
        ["**Bandosian chief engineer: Ask. I might answer.:**"] = "**Ingeniero jefe bandosiano: Pregunte. Podría responder.:**",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Zarador, Bandos' chief engineer. I construct weapons and equipment for Bandos and his army. Sometimes Bandos even accepts some of the work we create. I am in charge of the construction of the great siege incantation that will destroy Armadyl. I look forward to its completion, when I can watch the destruction of Armadyl from the tower. Bandos will ascend to a level no other god can reach."] = "Soy Zarador, el ingeniero jefe de Bandos. Construyo armas y equipos para Bandos y su ejército. A veces Bandos incluso acepta parte del trabajo que creamos. Estoy a cargo de la construcción del gran encantamiento de asedio que destruirá Armadyl. Espero con ansias su finalización, cuando pueda ver la destrucción de Armadyl desde la torre. Bandos ascenderá a un nivel que ningún otro dios puede alcanzar.",
        ["Where are you from?"] = "¿De dónde eres?",
        ["I have lived on Gielinor for many years. We've talked about Bandos' great battles, but I had never seen him. He is everything I hoped he would be. I am learning and strengthening by working with Bandos. I am privileged to serve him with my engineering skills."] = "He vivido en Gielinor durante muchos años. Hemos hablado de las grandes batallas de Bandos, pero nunca lo había visto. Él es todo lo que esperaba que fuera. Estoy aprendiendo y fortaleciéndome trabajando con Bandos. Tengo el privilegio de servirle con mis habilidades de ingeniería.",
        ["Why do you follow Bandos?"] = "¿Por qué sigues a Bandos?",
        ["Having been in many battles, I appreciate strength, and Bandos is the pinnacle of that strength. I am armed with the certainty that, with Bandos behind us, we will always be victorious. What a great feeling that is. He has fought in many battles and has never lost one. And with each battle won, he rewards those who have served him. That is why I serve."] = "Habiendo estado en muchas batallas, aprecio la fuerza, y Bandos es el pináculo de esa fuerza. Estoy armado con la certeza de que, con Bandos detrás nuestro, siempre saldremos victoriosos. Qué gran sentimiento es ese. Ha luchado en muchas batallas y nunca ha perdido ninguna. Y con cada batalla ganada, recompensa a quienes le han servido. Por eso sirvo.",
        ["How did you gain your engineering skills?"] = "¿Cómo adquiriste tus habilidades de ingeniería?",
        ["No, I will not talk of that, except to a warrior who could match me in battle."] = "No, no hablaré de eso, excepto con un guerrero que pueda igualarme en la batalla.",
        ["What happened in your previous battle?"] = "¿Qué pasó en tu batalla anterior?",
        ["I won't tell any old grunt how I learned the secrets of my trade."] = "No le contaré a ningún viejo gruñón cómo aprendí los secretos de mi oficio.",
        ["I have questions about my orders."] = "Tengo preguntas sobre mis pedidos.",
        ["Protect our caravans as they gather energy. Smash the Armadylean caravans. Build defenses along the roads. Show the power of Bandos to those who are unconvinced. I'm hoping we get more recruits like you."] = "Protege nuestras caravanas mientras acumulan energía. Aplasta las caravanas armadyleanas. Construye defensas a lo largo de las carreteras. Muestre el poder de Bandos a aquellos que no están convencidos. Espero que consigamos más reclutas como tú.",
        ["I have no more questions."] = "No tengo más preguntas.",
        ["Then go join the battle! For Bandos!"] = "¡Entonces únete a la batalla! ¡Por Bandos!",
        ["Bandos pitted a strong tribe against our village. They were stronger and more numerous. I felt that our time had come. Yet, I also felt Bandos watching over me. So I formed a plan. As they camped, I built cannons on the outskirts of our village. They pointed towards us, not our opponents. When the goblins woke, they chucked at our stupidity. Why build cannons that faced towards the village? So they gathered 'round the cannons, aimed them carefully, and lit the fuses. And it was then that I woke the spirits I had concealed in those false 'cannons', and commanded them to tear the metal shells apart from within. We took half their forces out in the explosion, and killed the rest in the confusion. Bandos personally congratulated me."] = "Bandos enfrentó a una tribu fuerte contra nuestra aldea. Eran más fuertes y más numerosos. Sentí que nuestro momento había llegado. Sin embargo, también sentí que Bandos me cuidaba. Entonces formé un plan. Mientras acampaban, construí cañones en las afueras de nuestra aldea. Nos señalaron a nosotros, no a nuestros oponentes. Cuando los duendes despertaron, se burlaron de nuestra estupidez. ¿Por qué construir cañones que apuntaran hacia el pueblo? Así que se reunieron alrededor de los cañones, los apuntaron con cuidado y encendieron las mechas. Y fue entonces cuando desperté a los espíritus que había escondido en esos falsos 'cañones' y les ordené que rompieran los caparazones metálicos desde dentro. Eliminamos a la mitad de sus fuerzas en la explosión y matamos al resto en la confusión. Bandos me felicitó personalmente.",
        ["At first I was just another grunt who relied purely on strength. I've got plenty of it, but there was always someone stronger than me. It would only be a matter of time before I slipped up. I learnt that I could achieve victory using other skills. I had a talent for shamanic art, and I could use them to create things here, engineer there. Since then, I've constructed great structures and weapons, and I've gained his favour that way."] = "Al principio yo era solo otro soldado que dependía únicamente de la fuerza. Tengo mucho, pero siempre hubo alguien más fuerte que yo. Sólo sería cuestión de tiempo antes de que cometiera un desliz. Aprendí que podía lograr la victoria usando otras habilidades. Tenía talento para el arte chamánico y podía usarlo para crear cosas aquí y diseñar allá. Desde entonces, he construido grandes estructuras y armas, y así me gané su favor.",
        ["Bold of you to be here. Perhaps you're suited to being a Bandosian."] = "Qué audaz de tu parte estar aquí. Quizás seas apto para ser bandosiano.",
        ["I cannot believe there's a battle going on to save the world, and no one invited the Bandosians. Graardor is assembling his forces now."] = "No puedo creer que haya una batalla para salvar el mundo y que nadie haya invitado a los bandosianos. Graardor está reuniendo sus fuerzas ahora.",
        ["It was never the plan to lose, but no one can say that we did not fight valiantly."] = "Nunca fue el plan perder, pero nadie puede decir que no luchamos valientemente.",
    },
    ["Zavistic Rarve"] = {
        ["What are you doing bothering me? Don't you think some of us have work to do?"] = "¿Qué haces molestándome? ¿No crees que algunos de nosotros tenemos trabajo que hacer?",
        ["I thought you were here to help?"] = "¿Pensé que estabas aquí para ayudar?",
        ["Well... I am, I suppose, anyway... we're very busy here, hurry up, what do you want?"] = "Bueno... Lo estoy, supongo, de todos modos... estamos muy ocupados aquí, apúrate, ¿qué quieres?",
        ["Select an option"] = "Seleccione una opción",
        ["What is there to do in the Wizards' Guild?"] = "¿Qué hay que hacer en el Gremio de Magos?",
        ["This is the finest wizards' establishment in the land. We have magic portals to the other towers of wizardry around Gielinor. We have a particularly wide collection of runes in our rune shop. We sell some of the finest mage robes in the land and we have a training area full of zombies for you to practice your magic on."] = "Este es el mejor establecimiento de magos del país. Tenemos portales mágicos a las otras torres de hechicería alrededor de Gielinor. Tenemos una colección particularmente amplia de runas en nuestra tienda de runas. Vendemos algunas de las mejores túnicas de mago del país y tenemos un área de entrenamiento llena de zombis para que practiques tu magia.",
        ["What are the requirements to get in the Wizards' Guild?"] = "¿Cuáles son los requisitos para entrar en el Gremio de Magos?",
        ["You need a magic level of 66, the high magic energy level is too dangerous for anyone below that level."] = "Necesitas un nivel de magia de 66, el alto nivel de energía mágica es demasiado peligroso para cualquiera que esté por debajo de ese nivel.",
        ["What do you do in the Guild?"] = "¿Qué haces en el gremio?",
        ["I'm the Grand Secretary for the Wizards' Guild, I have lots of correspondence to keep up with, as well as attending to the discipline of the more problematic guild members."] = "Soy el Gran Secretario del Gremio de Magos, tengo mucha correspondencia que mantener, además de ocuparme de la disciplina de los miembros más problemáticos del gremio.",
        ["Ok, thanks."] = "Bien, gracias.",
        ["What are you doing ringing that bell?! Don't you think some of us have work to do?"] = "¡¿Qué haces tocando ese timbre?! ¿No crees que algunos de nosotros tenemos trabajo que hacer?",
        ["But I was told to ring the bell if I wanted some attention."] = "Pero me dijeron que tocara el timbre si quería algo de atención.",
        ["Well...anyway...we're very busy here, hurry up what do you want?"] = "Bueno... de todos modos... estamos muy ocupados aquí, apúrate, ¿qué quieres?",
        ["What are you doing... Oh, it's you... sorry... didn't realise... what can I do for you?"] = "¿Qué estás haciendo... Oh, eres tú... lo siento... no me di cuenta... ¿qué puedo hacer por ti?",
        ["I'm here about the sicks... err Zogres"] = "Estoy aquí por los enfermos... err Zogres",
        ["Don'y you worry about Sithik, he's not likely to be moving from his bed for a long time. When he eventually does get better, he's going to be sent before a disciplinary tribunal, then we'll sort out what's what."] = "No te preocupes por Sithik, no es probable que se mueva de su cama por mucho tiempo. Cuando finalmente mejore, lo enviarán ante un tribunal disciplinario y luego resolveremos qué es qué.",
        ["Thank you for your help with all of this."] = "Gracias por tu ayuda con todo esto.",
        ["Ooohh, no thanks required. It's I who should be thanking you my friend... your investigative mind has shown how vigilant we really should be for this type of evil use of the magical arts."] = "Ooohh, no es necesario dar las gracias. Soy yo quien debería agradecerte amigo mío... tu mente investigadora ha demostrado cuán vigilantes realmente debemos estar ante este tipo de uso maligno de las artes mágicas.",
        ["I have a rather sandy problem that I'd like to palm off on you."] = "Tengo un problema bastante complicado que me gustaría dejarte en manos de ti.",
        ["*If the player has yet to complete One Foot in the Grave (miniquest)*"] = "*Si el player aún no ha completado Un pie en la tumba (minimisión)*",
        ["Thank you so much for helping to bring Clarence home and lock up his murderer! I only wish we could find the rest of him to truly put him to rest."] = "¡Muchas gracias por ayudar a traer a Clarence a casa y encerrar a su asesino! Sólo desearía que pudiéramos encontrar el resto de él para que realmente descansara.",
        ["*If the player has completed One Foot in the Grave (miniquest):*"] = "*Si el player ha completado Un pie en la tumba (minimisión):*",
        ["It's so good to have Clarence back in mostly one piece."] = "Es tan bueno tener a Clarence de regreso prácticamente en una sola pieza.",
        ["Back?"] = "¿Volver?",
        ["Yes indeed: he may not be alive, but he is buried in the grounds of the Wizards' Guild here. So he is back with us. All thanks to you."] = "Sí, efectivamente: puede que no esté vivo, pero está enterrado aquí en los terrenos del Gremio de Magos. Entonces él está de regreso con nosotros. Todo gracias a ti.",
        ["Pleased I could lend a hand."] = "Encantado de poder echarte una mano.",
        ["That was an incredibly bad pun. You know that puns are the lowest form of wheat?"] = "Ese fue un juego de palabras increíblemente malo. ¿Sabes que los juegos de palabras son la forma más baja de trigo?",
        ["Sorry, I don't seem to be able to help myself... I appear to have lost my head."] = "Lo siento, parece que no puedo evitarlo... Parece que he perdido la cabeza.",
        ["ARG! Another! Away with you!"] = "¡ARG! ¡Otro! ¡Fuera de aquí!",
        ["But..."] = "Pero...",
    },
