    ["Zimberfizz ashes"] = {
        ["*If you do not have four free spaces in your backpack:*"] = "*Si no tienes cuatro espacios libres en tu backpack:*",
        ["Thanks for holding onto those lamps for me, Zimberfizz!"] = "¡Gracias por guardarme esas lámparas, Zimberfizz!",
        ["Zimberfizz indicates that it was nothing."] = "Zimberfizz indica que no fue nada.",
        ["Can you tell me more about Soul Wars?"] = "¿Puedes contarme más sobre Soul Wars?",
        ["Can I have another tutorial?"] = "¿Puedo tener otro tutorial?",
